    // 压缩配置 - 四层压缩策略（参考Python s08设计）
    // L1 snip_compact: 最大消息数
    public static final int MAX_MESSAGES = 50;
    // L1 snip_compact: 保留头部消息数
    public static final int KEEP_HEAD = 3;
    // L2 micro_compact: 保留最近的工具结果数
    public static final int KEEP_RECENT = 3;
    // L3 tool_result_budget: 持久化阈值（字节）
    public static final int PERSIST_THRESHOLD = 30000;
    // L3 tool_result_budget: 单次消息最大字节数
    public static final int MAX_BYTES_PER_MESSAGE = 200_000;
    // L4 auto_compact: token阈值
    public static final int CONTEXT_LIMIT = 50000;

    // 兼容旧名称
    public static final int TOKEN_THRESHOLD = CONTEXT_LIMIT;
}

package com.hoppinzq.agent.tool.compact;

import com.anthropic.client.AnthropicClient;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.session.TranscriptRecord;
import lombok.extern.slf4j.Slf4j;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static com.hoppinzq.agent.constant.AIConstants.*;

/**
 * 上下文压缩器 - 四层压缩策略
 *
 * 压缩流程（参考Python s08设计）：
 * - L1: snip_compact      — 裁掉中间消息（消息数 > 50）
 * - L2: micro_compact     — 旧tool_result替换为占位符（保留最近3条）
 * - L3: tool_result_budget — 持久化大输出到磁盘（单次消息 > 30KB）
 * - L4: auto_compact      — LLM完整摘要（token超阈值）
 * - Emergency: reactive_compact — API返回prompt_too_long时触发
 *
 * 核心原则：cheap first, expensive last
 * 执行顺序：budget → snip → micro → auto
 *
 * @author hoppinzq
 */
@Slf4j
public class ContextCompactor {
    private final AnthropicClient client;
    private final String model;
    private final ObjectMapper mapper = new ObjectMapper();
    private final SessionManager sessionManager;

    public ContextCompactor(AnthropicClient client, String model, SessionManager sessionManager) {
        this.client = client;
        this.model = model;
        this.sessionManager = sessionManager;
    }

    /**
     * 兼容旧版本构造函数（不使用 SessionManager）
     */
    public ContextCompactor(AnthropicClient client, String model) {
        this(client, model, null);
    }

    // ============================== L1: snip_compact ==============================
    /**
     * L1: snip_compact — 裁掉中间消息（消息数超过50条时）
     *
     * 功能说明：
     * - 保留头部 KEEP_HEAD 条消息（初始上下文）
     * - 保留尾部消息（当前工作）
     * - 中间全部裁掉，替换为占位符
     * - 特殊处理：不能把 assistant(tool_use) 和后面的 user(tool_result) 拆开
     *
     * 执行时机：
     * - 每次LLM调用前检查消息数
     * - 当消息数 > MAX_MESSAGES 时触发
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> snipCompact(List<MessageParam> messages) {
        if (messages.size() <= MAX_MESSAGES) {
            return messages;
        }

        // 计算保留的头部和尾部
        int headEnd = KEEP_HEAD;
        int tailStart = messages.size() - (MAX_MESSAGES - KEEP_HEAD);

        // 边界条件1：不能把 assistant(tool_use) 和后面的 user(tool_result) 拆开
        if (headEnd > 0 && _messageHasToolUse(messages.get(headEnd - 1))) {
            while (headEnd < messages.size() && _isToolResultMessage(messages.get(headEnd))) {
                headEnd++;
            }
        }

        // 边界条件2：尾部起点也不能拆开 tool_use 和 tool_result
        if (tailStart > 0 && tailStart < messages.size()
                && _isToolResultMessage(messages.get(tailStart))
                && _messageHasToolUse(messages.get(tailStart - 1))) {
            tailStart--;
        }

        // 如果边界处理后头尾重叠，返回原消息列表
        if (headEnd >= tailStart) {
            return messages;
        }

        int snipped = tailStart - headEnd;

        // 构建压缩后的消息列表：头部 + 占位符 + 尾部
        List<MessageParam> newMessages = new ArrayList<>(messages.subList(0, headEnd));
        newMessages.add(MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content("[已省略 " + snipped + " 条对话历史消息]")
                .build());
        newMessages.addAll(messages.subList(tailStart, messages.size()));

        System.out.printf("\u001b[95m[snip compact]\u001b[0m 裁掉 %d 条消息（保留头部 %d 条）%n",
                snipped, KEEP_HEAD);

        return newMessages;
    }

    // ============================== L3: tool_result_budget ==============================
    /**
     * L3: tool_result_budget — 持久化大输出到磁盘
     *
     * 功能说明：
     * - 检查最后一条消息中的所有 tool_result
     * - 如果总字节数超过 MAX_BYTES_PER_MESSAGE，则持久化大的结果
     * - 按大小排序，优先持久化最大的结果
     * - 将持久化的结果替换为占位符，包含文件路径和预览
     *
     * 执行时机：
     * - 每次 tool_result 追加后检查
     * - 在 snip_compact 和 micro_compact 之后执行
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> toolResultBudget(List<MessageParam> messages) {
        if (messages.isEmpty()) {
            return messages;
        }

        // 获取最后一条消息
        MessageParam last = messages.get(messages.size() - 1);

        // 检查是否是用户消息且包含 tool_result
        if (!_isToolResultMessage(last)) {
            return messages;
        }

        // 收集所有 tool_result 块
        List<ToolResultInfo> toolResults = new ArrayList<>();
        if (last.content().isBlockParams()) {
            List<ContentBlockParam> contents = last.content().asBlockParams();
            for (int i = 0; i < contents.size(); i++) {
                ContentBlockParam block = contents.get(i);
                if (block.isToolResult()) {
                    toolResults.add(new ToolResultInfo(messages.size() - 1, i, block.toolResult().get()));
                }
            }
        }

        // 计算总字节数
        long totalBytes = 0;
        for (ToolResultInfo info : toolResults) {
            totalBytes += _getContentLength(info.result());
        }

        if (totalBytes <= MAX_BYTES_PER_MESSAGE) {
            return messages;
        }

        // 按大小排序（大到小）
        toolResults.sort((a, b) -> Long.compare(_getContentLength(b.result()), _getContentLength(a.result())));

        // 创建新的消息列表（复制）
        List<MessageParam> newMessages = new ArrayList<>(messages);
        MessageParam newLast = last;

        // 需要重建消息
        boolean needRebuild = true;
        List<ContentBlockParam> newBlocks = new ArrayList<>();

        // 处理每个 tool_result
        long currentTotal = totalBytes;
        for (ToolResultInfo info : toolResults) {
            if (currentTotal <= MAX_BYTES_PER_MESSAGE) {
                // 已经降到阈值以下，直接保留原始块
                if (last.content().isBlockParams()) {
                    newBlocks.add(last.content().asBlockParams().get(info.partIdx()));
                }
                break;
            }

            ToolResultBlockParam result = info.result();
            long contentLength = _getContentLength(result);

            if (contentLength <= PERSIST_THRESHOLD) {
                // 小于持久化阈值，保留原始内容
                if (last.content().isBlockParams()) {
                    newBlocks.add(last.content().asBlockParams().get(info.partIdx()));
                }
                continue;
            }

            // 持久化到磁盘
            String originalContent = _extractContentString(result);
            String persistedContent = _persistLargeOutput(result.toolUseId(), originalContent);

            // 创建替换的占位符块
            ToolResultBlockParam newResult = ToolResultBlockParam.builder()
                    .toolUseId(result.toolUseId())
                    .content(persistedContent)
                    .isError(false)
                    .build();

            newBlocks.add(ContentBlockParam.ofToolResult(newResult));

            // 更新总字节数
            currentTotal = currentTotal - contentLength + persistedContent.length();
        }

        // 重建最后一条消息
        if (needRebuild && !newBlocks.isEmpty()) {
            MessageParam.Content newContent = MessageParam.Content.ofBlockParams(newBlocks);
            newMessages.set(newMessages.size() - 1, MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(newContent)
                    .build());
        }

        System.out.printf("\u001b[95m[budget compact]\u001b[0m 持久化 %d 个大工具结果%n",
                toolResults.size());

        return newMessages;
    }

    // ============================== Emergency: reactive_compact ==============================
    /**
     * 紧急压缩 - 当API返回prompt_too_long时触发
     *
     * 功能说明：
     * - 保存完整对话记录到磁盘
     * - 生成对话摘要
     * - 保留首条用户消息 + 最近 KEEP_RECENT 条消息
     * - 中间用摘要替换
     *
     * 执行时机：
     * - API返回prompt_too_long错误时
     * - 作为最后的紧急手段
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> reactiveCompact(List<MessageParam> messages) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);

        try {
            // 步骤1：保存完整对话记录
            String transcriptPath = _saveTranscriptToDisk(messages);

            // 步骤2：生成摘要
            String summary = _generateSummary(messages);

            // 步骤3：构建压缩后的消息列表
            List<MessageParam> newMessages = new ArrayList<>();

            // 保留首条用户消息（如果存在）
            if (!messages.isEmpty()) {
                MessageParam first = messages.get(0);
                String roleStr = first._role().toString();
                if (roleStr.contains("user") || roleStr.contains("USER")) {
                    newMessages.add(first);
                }
            }

            // 添加摘要消息
            newMessages.add(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content("[紧急压缩以释放上下文]\n\n完整记录: " + transcriptPath + "\n\n" + summary)
                    .build());

            // 保留最近 KEEP_RECENT 条消息
            int tailStart = Math.max(0, messages.size() - KEEP_RECENT);

            // 边界条件：不能拆开 tool_use 和 tool_result
            if (tailStart > 0 && tailStart < messages.size()
                    && _isToolResultMessage(messages.get(tailStart))
                    && _messageHasToolUse(messages.get(tailStart - 1))) {
                tailStart--;
            }

            newMessages.addAll(messages.subList(tailStart, messages.size()));

            System.out.printf("\u001b[95m[reactive compact]\u001b[0m 保留首条 + 最近 %d 条，省略中间 %d 条%n",
                    KEEP_RECENT, messages.size() - newMessages.size());

            return newMessages;

        } catch (Exception e) {
            System.err.println("紧急压缩失败: " + e.getMessage());
            // 失败时返回原始消息列表
            return messages;
        }
    }

    // ============================== 辅助方法 ==============================

    /**
     * 判断消息是否包含 tool_use
     */
    private boolean _messageHasToolUse(MessageParam msg) {
        String roleStr = msg._role().toString();
        if (!roleStr.contains("assistant") && !roleStr.contains("ASSISTANT")) {
            return false;
        }

        if (!msg.content().isBlockParams()) {
            return false;
        }

        for (ContentBlockParam block : msg.content().asBlockParams()) {
            if (block.isToolUse()) {
                return true;
            }
        }

        return false;
    }

    /**
     * 判断消息是否包含 tool_result
     */
    private boolean _isToolResultMessage(MessageParam msg) {
        String roleStr = msg._role().toString();
        if (!roleStr.contains("user") && !roleStr.contains("USER")) {
            return false;
        }

        if (!msg.content().isBlockParams()) {
            return false;
        }

        for (ContentBlockParam block : msg.content().asBlockParams()) {
            if (block.isToolResult()) {
                return true;
            }
        }

        return false;
    }

    /**
     * 获取 tool_result 的内容长度
     */
    private long _getContentLength(ToolResultBlockParam result) {
        return _extractContentString(result).length();
    }

    /**
     * 从 ToolResultBlockParam 中提取内容字符串
     */
    private String _extractContentString(ToolResultBlockParam result) {
        // content() 返回 Optional<ToolResultBlockParam.Content>
        // 直接使用 toString() 获取内容字符串
        if (result.content().isPresent()) {
            Object content = result.content().get();
            // 尝试转换为字符串
            if (content instanceof String) {
                return (String) content;
            }
            // 其他类型，转换为字符串
            return content.toString();
        }
        return "";
    }

    /**
     * 持久化大输出到磁盘
     */
    private String _persistLargeOutput(String toolUseId, String output) {
        try {
            // 创建 tool-results 目录
            Path toolResultsDir = Paths.get(ROOT, ".task_outputs", "tool-results");
            Files.createDirectories(toolResultsDir);

            // 保存到文件
            Path filePath = toolResultsDir.resolve(toolUseId + ".txt");
            if (!Files.exists(filePath)) {
                Files.write(filePath, output.getBytes());
            }

            // 返回占位符
            String preview = output.length() > 2000 ? output.substring(0, 2000) : output;
            return String.format(
                    "<persisted-output>\n完整输出: %s\n预览:\n%s\n</persisted-output>",
                    filePath, preview
            );
        } catch (IOException e) {
            System.err.println("持久化工具结果失败: " + e.getMessage());
            return "[工具结果持久化失败: " + e.getMessage() + "]";
        }
    }

    /**
     * 保存对话记录到磁盘
     */
    private String _saveTranscriptToDisk(List<MessageParam> messages) throws IOException {
        Path transcriptDir = Paths.get(ROOT, ".transcripts");
        Files.createDirectories(transcriptDir);

        String timestamp = String.valueOf(System.currentTimeMillis());
        Path filePath = transcriptDir.resolve("transcript_" + timestamp + ".jsonl");

        List<String> lines = new ArrayList<>();
        for (MessageParam msg : messages) {
            lines.add(mapper.writeValueAsString(msg));
        }
        Files.write(filePath, lines);

        return filePath.toString();
    }

    /**
     * 生成对话摘要
     */
    private String _generateSummary(List<MessageParam> messages) {
        try {
            String conversationText = mapper.writeValueAsString(messages);
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            String prompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                    "1) 已完成的工作内容\n" +
                    "2) 当前状态\n" +
                    "3) 做出的关键决策\n" +
                    "4) 剩余工作\n" +
                    "5) 用户约束\n" +
                    "请简洁明了，但保留关键细节。\n\n" + conversationText;

            Message response = client.messages().create(MessageCreateParams.builder()
                    .model(model)
                    .messages(List.of(MessageParam.builder()
                            .role(MessageParam.Role.USER)
                            .content(prompt)
                            .build()))
                    .maxTokens(2000)
                    .build());

            return response.content().stream()
                    .filter(c -> c.isText())
                    .map(c -> c.text().map(TextBlock::text).orElse(""))
                    .collect(Collectors.joining("\n"));
        } catch (Exception e) {
            return "[摘要生成失败: " + e.getMessage() + "]";
        }
    }

    // ============================== 原有方法 ==============================

    /**
     * L2: micro_compact — 旧 tool_result 替换为占位符（保留最近3条）
     *
     * 功能说明：
     * - 遍历所有消息，收集工具调用和工具结果的位置信息
     * - 将旧的工具执行结果替换为简洁的占位符（如"[已执行: read_file]"）
     * - 保留最近KEEP_RECENT个工具结果不变，确保最近的工作上下文完整
     *
     * 执行时机：
     * - 每次调用LLM API前自动执行
     * - 在 snip_compact 和 tool_result_budget 之后执行
     * - 静默执行，对用户透明
     * - 高频执行以控制上下文大小
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> microCompact(List<MessageParam> messages) {
        // 【阶段1：信息收集】
        // 收集所有工具结果的位置信息（消息索引、内容块索引、结果数据）
        List<ToolResultInfo> toolResults = new ArrayList<>();

        // 建立工具ID到工具名称的映射，用于后续生成占位符
        Map<String, String> toolNameMap = new HashMap<>();

        // 遍历所有消息，构建工具结果索引和工具名称映射
        for (int i = 0; i < messages.size(); i++) {
            MessageParam msg = messages.get(i);
            try {
                // 兼容性处理：直接使用 _role() 获取原始值，避免 BigModel API 兼容性问题
                String roleStr = msg._role().toString();
                boolean isAssistant = roleStr.contains("assistant") || roleStr.contains("ASSISTANT");
                boolean isUser = roleStr.contains("user") || roleStr.contains("USER");
                MessageParam.Role role = isUser ? MessageParam.Role.USER : MessageParam.Role.ASSISTANT;

                if (isAssistant) {
                    // 处理助手消息：收集所有工具调用的ID和名称映射
                    if (msg.content().isBlockParams()) {
                        for (ContentBlockParam block : msg.content().asBlockParams()) {
                            if (block.isToolUse()) {
                                ToolUseBlockParam toolUse = block.toolUse().get();
                                toolNameMap.put(toolUse.id(), toolUse.name());
                            }
                        }
                    }
                } else if (isUser) {
                    // 处理用户消息：收集所有工具结果的位置信息
                    if (msg.content().isBlockParams()) {
                        List<ContentBlockParam> contents = msg.content().asBlockParams();
                        for (int j = 0; j < contents.size(); j++) {
                            ContentBlockParam block = contents.get(j);
                            if (block.isToolResult()) {
                                toolResults.add(new ToolResultInfo(i, j, block.toolResult().get()));
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // 处理消息时出错，打印错误信息并跳过该消息继续处理
                System.err.println("[微压缩] 处理第 " + i + " 条消息时出错: " + e.getMessage());
                e.printStackTrace();
                // 跳过此条消息，继续处理下一条
                continue;
            }
        }

        // 【阶段2：判断是否需要压缩】
        // 如果工具结果数量不超过保留数量，则无需压缩
        if (toolResults.size() <= KEEP_RECENT) {
            return messages;
        }

        // 【阶段3：执行压缩】
        List<MessageParam> newMessages = new ArrayList<>();
        int totalResults = toolResults.size();
        // 计算压缩阈值索引：在此索引之前的工具结果都将被替换为占位符
        int thresholdIndex = totalResults - KEEP_RECENT;

        // 当前遍历到的工具结果索引（从0开始递增）
        int currentResultIndex = 0;

        // 【阶段4：重建消息列表】
        for (MessageParam msg : messages) {
            // 直接使用 _role() 获取原始值，避免 BigModel API 兼容性问题
            String roleStr = msg._role().toString();
            boolean isUser = roleStr.contains("user") || roleStr.contains("USER");
            MessageParam.Role role = isUser ? MessageParam.Role.USER : MessageParam.Role.ASSISTANT;

            if (isUser) {
                if (!msg.content().isBlockParams()) {
                    newMessages.add(msg);
                    continue;
                }
                List<ContentBlockParam> oldBlocks = msg.content().asBlockParams();
                List<ContentBlockParam> newBlocks = new ArrayList<>();
                boolean changed = false;

                for (ContentBlockParam block : oldBlocks) {
                    if (block.isToolResult()) {
                        if (currentResultIndex < thresholdIndex) {
                            // 【压缩处理】将旧的工具执行结果替换为简洁的占位符
                            ToolResultBlockParam tr = block.toolResult().get();
                            String toolId = tr.toolUseId();
                            String toolName = toolNameMap.getOrDefault(toolId, "unknown");

                            // 占位符格式：[已执行: 工具名称]
                            // 这样可以保留工具调用历史，同时大幅减少token占用
                            newBlocks.add(ContentBlockParam.ofToolResult(
                                    ToolResultBlockParam.builder()
                                            .toolUseId(toolId)
                                            .content("[已执行: " + toolName + "]")
                                            .isError(false)
                                            .build()
                            ));
                            changed = true;
                        } else {
                            // 保留最近的工具结果（未被压缩的）
                            newBlocks.add(block);
                        }
                        currentResultIndex++;
                    } else {
                        // 非工具结果内容（如文本）直接保留
                        newBlocks.add(block);
                    }
                }

                if (changed) {
                    // 【消息重构】检测到内容被压缩，需要重新构建消息对象
                    // 将 List<ContentBlockParam> 转换为 Content 类型
                    if (!newBlocks.isEmpty()) {
                        MessageParam.Content content = MessageParam.Content.ofBlockParams(newBlocks);
                        newMessages.add(MessageParam.builder()
                                .role(role)
                                .content(content)
                                .build());
                    } else {
                        // 边界情况处理：如果压缩后newBlocks为空，保留原始消息
                        // 这种情况理论上不应发生，作为防御性编程处理
                        newMessages.add(msg);
                    }
                } else {
                    // 内容未改变，直接添加原消息
                    newMessages.add(msg);
                }
            } else {
                newMessages.add(msg);
            }
        }

        return newMessages;
    }

    /**
     * Layer 2: 自动压缩 - 完整对话压缩
     *
     * 功能说明：
     * - 将完整对话历史保存到 session 的 transcripts 或磁盘
     * - 请求LLM生成对话摘要（包含已完成的工作、当前状态、关键决策）
     * - 用摘要消息替换原始消息列表，实现上下文压缩
     *
     * 触发条件：
     * - 当估算的token数量超过 TOKEN_THRESHOLD 时自动触发
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表（仅包含摘要消息）
     */
    public List<MessageParam> autoCompact(List<MessageParam> messages) {
        return autoCompact(messages, "auto");
    }

    /**
     * Layer 2/3: 完整对话压缩（可指定压缩原因）
     *
     * @param messages 原始消息列表
     * @param reason 压缩原因（auto/manual）
     * @return 压缩后的消息列表
     */
    public List<MessageParam> autoCompact(List<MessageParam> messages, String reason) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);
        int estimatedTokens = estimateTokens(messages);
        int messageCount = messages.size();

        // 声明 transcriptPath 变量（方法级别）
        String transcriptPath = null;

        // 【步骤1】保存完整对话记录
        // 优先使用 SessionManager，如果不可用则保存到磁盘
        try {
            if (sessionManager != null) {
                // 使用 SessionManager 保存，将在步骤3中添加 transcript 记录
                transcriptPath = "会话 " + sessionManager.getSessionId() + " 的压缩记录";
                System.out.println("[准备压缩] 消息数: " + messageCount + ", 估算tokens: " + estimatedTokens);
            } else {
                // 保存到磁盘的 .transcripts/ 目录
                Path path = Paths.get(ROOT, ".transcripts");
                if (!Files.exists(path)) {
                    Files.createDirectories(path);
                }
                Path filePath = path.resolve("transcript_" + System.currentTimeMillis() + ".jsonl");
                List<String> lines = new ArrayList<>();
                for (MessageParam msg : messages) {
                    lines.add(mapper.writeValueAsString(msg));
                }
                Files.write(filePath, lines);
                transcriptPath = filePath.toString();
                System.out.println("[对话记录已保存: " + transcriptPath + "]");
            }

            // 【步骤2】生成对话摘要
            // 将消息列表转换为文本（限制在80000字符以内以避免超出API限制）
            String conversationText = messages.toString();
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            // 构建摘要提示词，要求LLM生成包含关键信息的简洁摘要
            String summaryPrompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                    "1) 已完成的工作内容\n" +
                    "2) 当前状态\n" +
                    "3) 做出的关键决策\n" +
                    "请简洁明了，但保留关键细节。\n\n" + conversationText;

            Message summaryMsg = client.messages().create(MessageCreateParams.builder()
                    .model(MODEL)
                    .messages(List.of(MessageParam.builder()
                            .role(MessageParam.Role.USER)
                            .content(summaryPrompt)
                            .build()))
                    .maxTokens(2000)
                    .build());

            String summary = summaryMsg.content().stream()
                    .filter(ContentBlock::isText)
                    .map(cb -> cb.text().get().text())
                    .collect(Collectors.joining());

            // 【步骤3】将压缩记录保存到 SessionManager（如果可用）
            if (sessionManager != null) {
                try {
                    // 创建 transcript 记录
                    TranscriptRecord record = TranscriptRecord.builder()
                            .timestamp(timestamp)
                            .messageCount(messageCount)
                            .estimatedTokens(estimatedTokens)
                            .summary(summary)
                            .reason(reason)
                            .build();
                    sessionManager.recordTranscript(record);
                    System.out.println("[压缩记录已保存到会话]");
                } catch (Exception e) {
                    System.err.println("[压缩记录保存失败] " + e.getMessage());
                }
            }

            // 【步骤4】构建压缩后的新消息列表
            // 包含两条消息：用户消息（告知对话已压缩并提供摘要）+ 助手确认消息
            List<MessageParam> newHistory = new ArrayList<>();
            newHistory.add(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content("[对话已压缩。完整记录: " + transcriptPath + "]\n\n" + summary)
                    .build());
            newHistory.add(MessageParam.builder()
                    .role(MessageParam.Role.ASSISTANT)
                    .content("收到。我已从摘要中获取了上下文。继续工作。")
                    .build());

            return newHistory;

        } catch (IOException e) {
            // 压缩失败时返回原始消息列表，确保对话不中断
            System.err.println("自动压缩时出错: " + e.getMessage());
            return messages;
        }
    }

    /**
     * 保存对话记录到磁盘
     *
     * 功能说明：
     * - 在 .transcripts 目录下创建以时间戳命名的 JSONL 文件
     * - 每条消息序列化为JSON后写入一行
     * - JSONL格式便于后续读取和分析
     *
     * 注意：虽然 SessionManager 已经存储会话数据，但这里保留磁盘备份
     * 因为 SessionManager 存储的是压缩后的消息，压缩前的完整对话需要额外保存
     *
     * @param messages 要保存的消息列表
     * @return 保存的文件路径，失败时返回错误标识
     */
    private String saveTranscript(List<MessageParam> messages) {
        try {
            // 创建transcript目录（如果不存在）
            Path transcriptDir = Paths.get(ROOT, ".transcripts");
            Files.createDirectories(transcriptDir);

            // 使用时间戳生成唯一文件名：transcript_<时间戳>.jsonl
            String timestamp = String.valueOf(System.currentTimeMillis());
            String transcriptPath = transcriptDir.resolve("transcript_" + timestamp + ".jsonl").toString();

            // 使用BufferedWriter逐行写入JSON格式的消息
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(transcriptPath))) {
                for (MessageParam msg : messages) {
                    String json = mapper.writeValueAsString(msg);
                    writer.write(json);
                    writer.newLine();
                }
            }

            log.info("[对话记录已保存: {}]", transcriptPath);
            return transcriptPath;
        } catch (IOException e) {
            log.error("保存对话记录失败", e);
            return "[对话记录保存失败]";
        }
    }

    /**
     * 请求LLM生成对话摘要
     *
     * 功能说明：
     * - 将消息列表序列化为文本（限制80000字符）
     * - 构建专门的摘要提示词
     * - 调用LLM API生成结构化的对话摘要
     *
     * @param messages 要摘要的消息列表
     * @return 生成的摘要文本，失败时返回错误信息
     */
    private String generateSummary(List<MessageParam> messages) {
        try {
            // 将消息序列化为JSON字符串（作为摘要的输入）
            String conversationText = mapper.writeValueAsString(messages);
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            // 构建中文摘要提示词
            String prompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                "1) 已完成的工作内容\n" +
                "2) 当前状态\n" +
                "3) 做出的关键决策\n" +
                "请简洁明了，但保留关键细节。\n\n" + conversationText;
            
            // 构建API请求参数
            MessageCreateParams params = MessageCreateParams.builder()
                .model(model)
                .messages(List.of(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(prompt)
                    .build()))
                .maxTokens(2000)  // 限制摘要长度为2000 tokens
                .build();

            // 调用LLM生成摘要
            Message response = client.messages().create(params);
            // 提取并拼接所有文本块
            return response.content().stream()
                .filter(c -> c.isText())
                .map(c -> c.text().map(TextBlock::text).orElse(""))
                .collect(Collectors.joining("\n"));
        } catch (Exception e) {
            log.error("生成摘要失败", e);
            return "[摘要生成失败: " + e.getMessage() + "]";
        }
    }

    /**
     * 估算消息列表的token数量
     *
     * 说明：
     * - 使用粗略估算方法：约4个字符 ≈ 1个token
     * - 将消息列表序列化为JSON后计算长度
     * - 用于判断是否需要触发自动压缩
     *
     * 注意：
     * - 这是简化估算，实际token数量可能有所不同
     * - 对于精确控制，应使用官方的tokenizer工具
     *
     * @param messages 要估算的消息列表
     * @return 估算的token数量
     */
    public static int estimateTokens(List<MessageParam> messages) {
        try {
            String json = OBJECT_MAPPER.writeValueAsString(messages);
            return json.length() / 4;
        } catch (Exception e) {
            // 序列化失败时返回0，表示无法估算
            return 0;
        }
    }

    /**
     * 工具结果信息记录
     *
     * 用于在微压缩过程中跟踪工具结果的位置信息：
     * - msgIdx: 消息在消息列表中的索引
     * - partIdx: 工具结果在消息内容块中的索引
     * - result: 工具执行结果的完整数据
     *
     * 通过这些信息，可以精确定位和替换需要压缩的工具结果
     */
    private static record ToolResultInfo(int msgIdx, int partIdx, ToolResultBlockParam result) {}
}

package com.hoppinzq.agent.base;

import com.anthropic.client.AnthropicClient;
import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.hoppinzq.agent.command.AgentCommandHandler;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.session.SubAgentSessionResult;
import com.hoppinzq.agent.tool.ToolDefinition;
import com.hoppinzq.agent.tool.skill.SkillLoader;
import lombok.Data;

import java.util.*;

import static com.hoppinzq.agent.constant.AIConstants.*;

/**
 * 智能体基类
 * @author hoppinzq
 */
@Data
public class ZQAgent {
    private String systemPrompt;
    private final Scanner scanner;
    private final String model;
    protected final AnthropicClient client;
    private final List<ToolDefinition> tools;
    protected List<MessageParam> messageParams = new ArrayList<>();
    private String taskResult;
    private boolean taskCompleted = false;
    /**
     * 可选的命令处理器；设置后可处理 /stats、/usage、/skills、/exit 等特殊命令。
     */
    private AgentCommandHandler commandHandler;

    /**
     * 会话管理器
     */
    protected SessionManager sessionManager;

    public ZQAgent(AnthropicClient client, String model, List<ToolDefinition> tools) {
        this.client = client;
        this.model = model;
        this.scanner = new Scanner(System.in);
        this.tools = tools;
    }

    /**
     * 设置会话管理器，同时初始化命令处理器。
     * 子类可以重写此方法以提供额外的命令处理器（如 compact 命令）。
     */
    public void setSessionManager(SessionManager sessionManager, SkillLoader skillLoader) {
        this.sessionManager = sessionManager;
        this.commandHandler = sessionManager != null ? createCommandHandler(sessionManager, skillLoader) : null;
    }

    /**
     * 创建命令处理器。子类可以重写此方法以提供自定义的命令处理器。
     *
     * @param sessionManager 会话管理器
     * @param skillLoader 技能加载器
     * @return 命令处理器，默认不包含 compact 命令支持
     */
    protected AgentCommandHandler createCommandHandler(SessionManager sessionManager, SkillLoader skillLoader) {
        return new AgentCommandHandler(sessionManager, skillLoader, null);
    }

    public void run() {
        if (sessionManager != null) {
            int n = sessionManager.historySize();
            if (n > 0) {
                sessionManager.populate(messageParams);
                System.out.printf("\u001b[90m已恢复会话 %s，共 %d 条历史消息\u001b[0m%n",
                        sessionManager.getSessionId(), n);
            } else {
                System.out.printf("\u001b[90m新会话 %s\u001b[0m%n", sessionManager.getSessionId());
            }
        }
        System.out.println("开始对话吧（输入 /stats 查看统计，/usage 查看明细，/skills 查看技能，/tokens 查看上下文，/transcripts 查看压缩历史，/compact 手动压缩，/exit 退出）");
        while (true) {
            System.out.print("\u001b[94m你\u001b[0m: ");
            String userInput = scanner.nextLine();
            if (userInput.isEmpty()) {
                continue;
            }
            // 特殊命令：不发送给 LLM
            if (commandHandler != null && commandHandler.isCommand(userInput)) {
                commandHandler.handleCommand(userInput);
                continue;
            }
            MessageParam userMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(userInput)
                    .build();
            appendMessage(userMessage);

            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                System.out.println("错误: " + e.getMessage());
                e.printStackTrace();
                continue;
            }
            appendMessage(message.toParam());
            recordUsageIfNeeded(message);
            // 每次 create 后都打印 assistant 的文本输出，避免纯文本回复（无工具调用）被静默吞掉
            printText(message);

            // 官方推荐的 canonical agentic loop：以 stop_reason == TOOL_USE 为循环条件
            while (isToolUse(message)) {
                MessageParam toolResultMessage = executeToolCalls(message);
                appendMessage(toolResultMessage);

                try {
                    message = chatMessage(messageParams);
                } catch (Exception e) {
                    System.out.println("错误: " + e.getMessage());
                    break;
                }
                appendMessage(message.toParam());
                recordUsageIfNeeded(message);
                printText(message);
            }
            // 非 TOOL_USE 退出：检查是否被截断
            warnIfTruncated(message);
        }
    }

    /**
     * 打印 assistant 消息中的所有文本块。空文本跳过。
     */
    private void printText(Message message) {
        for (ContentBlock content : message.content()) {
            if (content.isText()) {
                String text = content.text().map(TextBlock::text).orElse("");
                if (!text.isBlank()) {
                    System.out.printf("\u001b[93mAI\u001b[0m: %s%n", text);
                }
            }
        }
    }

    /**
     * 判断是否需要继续工具循环。
     * <p>官方推荐以 {@code stop_reason == TOOL_USE} 而非遍历 content，
     * 因为模型可能输出空 tool_use 或被 max_tokens 截断，stop_reason 更可靠。
     */
    private boolean isToolUse(Message message) {
        return message.stopReason()
                .map(StopReason.TOOL_USE::equals)
                .orElse(false);
    }

    /** 命中 MAX_TOKENS 时打印警告，避免静默截断工具调用导致死循环。 */
    private void warnIfTruncated(Message message) {
        boolean maxTokens = message.stopReason()
                .map(StopReason.MAX_TOKENS::equals)
                .orElse(false);
        if (maxTokens) {
            System.out.printf("\u001b[91m[警告]\u001b[0m 本轮回复被 max_tokens=%d 截断，工具调用可能不完整。建议调大 MAX_TOKENS。%n",
                    MAX_TOKENS);
        }
    }

    /**
     * 执行一轮 assistant 回复中的所有工具调用，返回封装好的 user 角色 tool_result 消息。
     * <p>文本块已由 {@link #printText(Message)} 处理，这里只负责工具；
     * 找不到工具或执行抛异常都会被标记为 isError=true 回灌给模型。
     */
    private MessageParam executeToolCalls(Message message) {
        List<ContentBlockParam> toolResults = new ArrayList<>();
        for (ContentBlock content : message.content()) {
            if (!content.isToolUse()) {
                continue;
            }
            ToolUseBlock toolUse = content.asToolUse();
            System.out.printf("\u001b[96m工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

            String toolResult = null;
            Exception toolError = null;
            ToolDefinition matched = null;
            for (ToolDefinition tool : tools) {
                if (tool.getName().equals(toolUse.name())) {
                    matched = tool;
                    break;
                }
            }
            if (matched == null) {
                toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                System.out.printf("\u001b[91m错误\u001b[0m: %s%n", toolError.getMessage());
            } else {
                try {
                    toolResult = invokeTool(matched, toolUse._input());
                    System.out.printf("\u001b[92m结果\u001b[0m: %s%n", toolResult);
                } catch (Exception e) {
                    toolError = e;
                    System.out.printf("\u001b[91m错误\u001b[0m: %s%n", e.getMessage());
                    e.printStackTrace();
                }
            }

            toolResults.add(ContentBlockParam.ofToolResult(
                    ToolResultBlockParam.builder()
                            .toolUseId(toolUse.id())
                            .content(toolError != null ? toolError.getMessage() : toolResult)
                            .isError(toolError != null)
                            .build()
            ));
        }
        return MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(MessageParam.Content.ofBlockParams(toolResults))
                .build();
    }

    /**
     * 记录本次 LLM 调用的 token 使用情况（若设置了 SessionManager）。
     */
    private void recordUsageIfNeeded(Message message) {
        if (sessionManager != null && message.usage() != null) {
            sessionManager.recordUsage(message.usage());
        }
    }

    /**
     * 向 messageParams 追加一条消息；若设置了 {@link SessionManager}，
     * 同步持久化。所有需要记录历史的追加都应走此方法。
     */
    protected void appendMessage(MessageParam param) {
        messageParams.add(param);
        if (sessionManager != null) {
            sessionManager.onMessageAppended(param);
        }
    }

    /**
     * 工具执行后的回调钩子，子类可重写以注入额外内容（如提醒、压缩等）。
     * 注意：基类的 {@link #executeToolCalls(Message)} 不再调用此方法；
     * 仅为兼容已有子类重写而保留。
     */
    protected void onToolExecution(List<ContentBlockParam> toolResults) {
        // 默认空实现
    }

    private String invokeTool(ToolDefinition tool, JsonValue input) {
        if (tool.getType() == null) {
            if (input.asObject().isEmpty()) {
                throw new IllegalArgumentException("工具 '" + tool.getName() + "' 参数不是 JSON 对象");
            }
            ObjectNode root = OBJECT_MAPPER.createObjectNode();
            root.set("input", input.convert(JsonNode.class));
            root.put("tool_name", tool.getName());
            return tool.getFunction().apply(root.toString());
        } else {
            return tool.getFunction().apply(Objects.requireNonNull(input.convert(tool.getType())).toString());
        }
    }

    protected Message chatMessage(List<MessageParam> messageParams){
        // 准备工具配置
        List<ToolUnion> anthropicTools = new ArrayList<>();
        for (ToolDefinition tool : tools) {
            anthropicTools.add(ToolUnion.ofTool(
                    Tool.builder()
                            .name(tool.getName())
                            .description(tool.getDescription())
                            .inputSchema(tool.getInputSchema())
                            .build()
            ));
        }
        MessageCreateParams.Builder messageBuilder = MessageCreateParams.builder()
                .model(model)
                .messages(messageParams)
                .tools(anthropicTools);

        if(systemPrompt != null && !systemPrompt.isEmpty()){
            messageBuilder.system(systemPrompt);
        }

         messageBuilder.maxTokens(MAX_TOKENS);

        MessageCreateParams params = messageBuilder.build();
        return client.messages().create(params);
    }

    public String runTask(String prompt) {
        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return "Error: " + e.getMessage();
            }
            messageParams.add(message.toParam());

            List<ContentBlockParam> toolResults = new ArrayList<>();
            boolean hasToolUse = false;

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                } else if (content.isToolUse()) {
                    hasToolUse = true;
                    ToolUseBlock toolUse = content.asToolUse();
                    System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                    if ("task_completed".equals(toolUse.name())) {
                        try {
                            JsonValue input = toolUse._input();
                            Optional<Map<String, JsonValue>> object = input.asObject();
                            if (object.isPresent()) {
                                JsonValue res = object.get().get("result");
                                if (res != null && res.asString().isPresent()) {
                                    return res.asString().get().toString();
                                }
                            }
                            return "Task completed.";
                        } catch (Exception e) {
                            return "Error parsing task_completed: " + e.getMessage();
                        }
                    }

                    String toolResult = null;
                    Exception toolError = null;
                    boolean toolFound = false;

                    for (ToolDefinition tool : tools) {
                        if (tool.getName().equals(toolUse.name())) {
                            try {
                                JsonValue input = toolUse._input();
                                toolResult = invokeTool(tool, input);
                                System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                            } catch (Exception e) {
                                toolError = e;
                                System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                                e.printStackTrace();
                            }
                            toolFound = true;
                            break;
                        }
                    }

                    if (!toolFound) {
                        toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                    }

                    if (toolError != null) {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolError.getMessage())
                                        .isError(true)
                                        .build()
                        ));
                    } else {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolResult)
                                        .isError(false)
                                        .build()
                        ));
                    }
                }
            }

            if (!hasToolUse) {
                // Return the text response as result if no tools used
                warnIfTruncated(message);
                return message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
            }
            MessageParam.Content content = MessageParam.Content.ofBlockParams(toolResults);
            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(content)
                    .build();
            messageParams.add(toolResultMessage);
        }
    }

    /**
     * 执行任务并返回包含 token 使用情况的结果
     *
     * @param prompt 任务提示词
     * @return 包含结果和 token 使用情况的 SubAgentSessionResult
     */
    public SubAgentSessionResult runTaskWithTokenUsage(String prompt) {
        long totalInputTokens = 0;
        long totalOutputTokens = 0;

        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return SubAgentSessionResult.error("Error: " + e.getMessage());
            }
            messageParams.add(message.toParam());

            // 累积 token 使用情况
            if (message.usage() != null) {
                totalInputTokens += message.usage().inputTokens();
                totalOutputTokens += message.usage().outputTokens();
            }

            List<ContentBlockParam> toolResults = new ArrayList<>();
            boolean hasToolUse = false;

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    if (!result.isBlank()) {
                        System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                    }
                } else if (content.isToolUse()) {
                    hasToolUse = true;
                    ToolUseBlock toolUse = content.asToolUse();
                    System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                    if ("task_completed".equals(toolUse.name())) {
                        try {
                            JsonValue input = toolUse._input();
                            Optional<Map<String, JsonValue>> object = input.asObject();
                            if (object.isPresent()) {
                                JsonValue res = object.get().get("result");
                                if (res != null && res.asString().isPresent()) {
                                    return SubAgentSessionResult.success(
                                            res.asString().get().toString(),
                                            totalInputTokens,
                                            totalOutputTokens);
                                }
                            }
                            return SubAgentSessionResult.success("Task completed.", totalInputTokens, totalOutputTokens);
                        } catch (Exception e) {
                            return SubAgentSessionResult.error("Error parsing task_completed: " + e.getMessage());
                        }
                    }

                    String toolResult = null;
                    Exception toolError = null;
                    boolean toolFound = false;

                    for (ToolDefinition tool : tools) {
                        if (tool.getName().equals(toolUse.name())) {
                            try {
                                JsonValue input = toolUse._input();
                                toolResult = invokeTool(tool, input);
                                System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                            } catch (Exception e) {
                                toolError = e;
                                System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                                e.printStackTrace();
                            }
                            toolFound = true;
                            break;
                        }
                    }

                    if (!toolFound) {
                        toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                    }

                    if (toolError != null) {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolError.getMessage())
                                        .isError(true)
                                        .build()
                        ));
                    } else {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolResult)
                                        .isError(false)
                                        .build()
                        ));
                    }
                }
            }

            if (!hasToolUse) {
                warnIfTruncated(message);
                String result = message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
                return SubAgentSessionResult.success(result, totalInputTokens, totalOutputTokens);
            }

            MessageParam.Content content = MessageParam.Content.ofBlockParams(toolResults);
            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(content)
                    .build();
            messageParams.add(toolResultMessage);
        }
    }
}

package com.hoppinzq.agent.tool;

import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.Tool;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.hoppinzq.agent.Agent06;
import com.hoppinzq.agent.tool.schema.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

import static com.hoppinzq.agent.constant.AIConstants.OBJECT_MAPPER;

/**
 * ToolDefinition 工具定义类
 * @author hoppinzq
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class ToolDefinition {
    // toolCall 或者 MCP需要用的三个字段
    private String name;
    private String description;
    private Tool.InputSchema inputSchema;

    // 工具的参数类型和处理函数
    private Class<?> type;
    private Function<String, String> function;
    private TypedToolInvoker typedInvoker;

    @FunctionalInterface
    public interface TypedToolFunction<T> {
        String apply(T input) throws Exception;
    }

    @FunctionalInterface
    public interface TypedToolInvoker {
        String apply(Object input) throws Exception;
    }

    public ToolDefinition(String name, String description, Tool.InputSchema inputSchema, Class<?> type, Function<String, String> function) {
        this.name = name;
        this.description = description;
        this.inputSchema = inputSchema;
        this.type = type;
        this.function = function;
        this.typedInvoker = null;
    }

    public <T> ToolDefinition(String name, String description, Tool.InputSchema inputSchema, Class<T> type, TypedToolFunction<T> typedFunction) {
        this.name = name;
        this.description = description;
        this.inputSchema = inputSchema;
        this.type = type;
        this.function = null;
        this.typedInvoker = input -> typedFunction.apply(type.cast(input));
    }

    public String invoke(Object convertedInput) throws Exception {
        if (typedInvoker != null) {
            return typedInvoker.apply(convertedInput);
        }
        if (function != null) {
            if (convertedInput instanceof String) {
                return function.apply((String) convertedInput);
            }
            return function.apply(OBJECT_MAPPER.writeValueAsString(convertedInput));
        }
        throw new IllegalStateException("没有该工具的处理方法: " + name);
    }

    public static ToolDefinition ReadFileDefinition = new ToolDefinition(
            "read_file",
            "读取指定相对文件路径的内容。适用于需要查看文件内容的场景，支持查看各种类型文件的完整内容。请注意，此工具仅用于文件，不可用于目录。",
            createInputSchema(
                    Map.of("path", createProperty("string", "工作目录中文件的相对路径。")),
                    List.of("path")
            ),
            ReadFileInput.class,
            Tools::readFile
    );

    public static ToolDefinition WriteFileDefinition = new ToolDefinition(
            "write_file",
            "将内容写入文件。如果文件不存在，则创建该文件。",
            createInputSchema(
                    Map.of(
                            "path", createProperty("string", "文件的路径"),
                            "content", createProperty("string", "要写入的内容")
