            ),
            LoadSkillInput.class,
            Tools::skillLoad
    );

    /**
     * 待办事项工具定义
     * 用于管理任务列表，支持添加、更新或完成任务
     */
    public static ToolDefinition TodoDefinition = new ToolDefinition(
            "todo",
            "管理待办事项列表。使用此工具可以添加、更新或完成任务。支持任务状态追踪，包括待处理、进行中和已完成三种状态。",
            createInputSchema(
                    Map.of("todos",
                            Map.of(
                                    "type", "array",
                                    "description", "待办事项列表",
                                    "items", Map.of(
                                            "type", "object",
                                            "properties", Map.of(
                                                    "id", Map.of("type", "string", "description", "任务的唯一标识符"),
                                                    "content", Map.of("type", "string", "description", "待办事项的内容描述"),
                                                    "status", Map.of(
                                                            "type", "string",
                                                            "enum", List.of("pending", "in_progress", "completed"),
                                                            "description", "任务状态：pending-待处理, in_progress-进行中, completed-已完成"
                                                    )
                                            ),
                                            "required", List.of("id", "content", "status")
                                    )
                            )
                    ),
                    List.of("todos")
            ),
            TodoInput.class,
            Agent06.todoManager::updateTodos
    );


    /**
     * 对话压缩工具定义
     * <p>
     * 手动触发对话压缩，由 LLM 调用时立即执行完整的上下文压缩。
     * </p>
     */
    public static ToolDefinition ContentCompactDefinition = new ToolDefinition(
            "compact",
            "手动触发对话压缩。当上下文过大时使用此工具。\n\n" +
                    "使用场景：\n" +
                    "• 对话历史过长，占用大量 token 时\n" +
                    "• 需要保持核心信息但压缩历史对话时\n" +
                    "• 系统提示接近 token 限制时\n\n" +
                    "功能说明：\n" +
                    "• 压缩历史对话，保留关键信息\n" +
                    "• 可选指定压缩重点（focus 参数）\n" +
                    "• 压缩后保留最近的工作上下文",
            createInputSchema(
                    Map.of("focus", ToolDefinition.createProperty("string", "压缩重点，指定在摘要中保留的内容类型（可选）")),
                    List.of()
            ),
            CompactInput.class,
            Tools::compact
    );

    /**
     * 创建属性定义
     */
    public static Map<String, Object> createProperty(String type, String description) {
        Map<String, Object> property = new HashMap<>();
        property.put("type", type);
        property.put("description", description);
        return property;
    }

    /**
     * 创建InputSchema
     */
    public static Tool.InputSchema createInputSchema(Map<String, Object> properties, List<String> required) {
        ObjectNode propertiesNode = OBJECT_MAPPER.valueToTree(properties);

        Tool.InputSchema.Builder schemaBuilder = Tool.InputSchema.builder()
                .properties(JsonValue.fromJsonNode(propertiesNode));

        if (required != null && !required.isEmpty()) {
            schemaBuilder.required(required);
        }

        return schemaBuilder.build();
    }
}

package com.hoppinzq.agent.session;

import com.anthropic.models.messages.MessageParam;
import com.anthropic.models.messages.Usage;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 会话编排器：维护当前 {@code sessionId} 与内存中的消息副本，
 * 在每条消息追加时自动持久化到 {@link SessionStore}。
 * <p>与 agent 解耦：agent 只需在添加消息时调用 {@link #onMessageAppended(MessageParam)}，
 * 启动时调用 {@link #populate(List)} 即可恢复历史。
 *
 * <h3>典型用法</h3>
 * <pre>{@code
 *   SessionManager sm = new SessionManager();
 *   if (args.length > 0 && sm.resume(args[0])) {
 *       System.out.println("已恢复会话 " + sm.getSessionId());
 *   } else {
 *       sm.startNew();
 *       System.out.println("新会话 " + sm.getSessionId());
 *   }
 *   agent.setSessionManager(sm);
 *   sm.populate(agent.getMessageParams());   // 由 ZQAgent.run 启动时自动调用
 *   agent.run();
 * }</pre>
 *
 * @author hoppinzq
 */
public class SessionManager {

    private static final DateTimeFormatter ID_FMT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

    private final SessionStore store;
    private final MessageConverter converter;
    private SessionData sessionData = SessionData.builder().build();
    private String sessionId;

    public SessionManager() {
        this(new SessionStore(), new MessageConverter());
    }

    public SessionManager(SessionStore store, MessageConverter converter) {
        this.store = store;
        this.converter = converter;
    }

    // ============================== 生命周期 ==============================

    /**
     * 创建一个新会话，生成形如 {@code yyyyMMdd-HHmmss-XXXX} 的 ID。
     */
    public String startNew() {
        this.sessionId = generateId();
        this.sessionData = SessionData.builder()
                .messages(new ArrayList<>())
                .usage(new ArrayList<>())
                .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        // 预先落盘一份空文件，便于 listIds 时就能看到
        persist();
        return this.sessionId;
    }

    /**
     * 恢复指定会话。
     *
     * @return 若会话存在且非空返回 {@code true}；否则返回 {@code false}（仍会以该 id 继续会话）
     */
    public boolean resume(String sessionId) {
        this.sessionId = sessionId;
        this.sessionData = store.load(sessionId);

        // 验证会话数据完整性：检查是否有未完成的 tool_use
        if (!this.sessionData.getMessages().isEmpty()) {
            boolean hasIncompleteToolUse = validateMessageIntegrity();
            if (hasIncompleteToolUse) {
                System.out.printf("\u001b[93m警告: 会话 %s 数据不完整，包含未完成的 tool_use，已清理\u001b[0m%n", sessionId);
                // 清理会话数据
                this.sessionData = SessionData.builder()
                        .messages(new ArrayList<>())
                        .usage(new ArrayList<>())
                        .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                        .build();
                // 清空磁盘上的会话文件
                try {
                    store.save(sessionId, this.sessionData);
                } catch (Exception e) {
                    // 忽略保存失败
                }
                return false;
            }
        }

        boolean hasMessages = !this.sessionData.getMessages().isEmpty();
        // 若有历史 usage 数据，打印统计摘要
        if (hasMessages && !sessionData.getUsage().isEmpty()) {
            printSummary();
        }
        return hasMessages;
    }

    /**
     * 验证消息序列的完整性，检查是否有未完成的 tool_use。
     *
     * @return 如果发现未完成的 tool_use 返回 true，否则返回 false
     */
    private boolean validateMessageIntegrity() {
        Set<String> completedToolUses = new HashSet<>();
        Set<String> pendingToolUses = new HashSet<>();

        for (SessionMessage sm : sessionData.getMessages()) {
            if (sm.getBlocks() == null) {
                continue;
            }
            for (SessionBlock block : sm.getBlocks()) {
                if ("tool_use".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.add(toolUseId);
                    }
                } else if ("tool_result".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.remove(toolUseId);
                        completedToolUses.add(toolUseId);
                    }
                }
            }
        }

        // 如果还有未完成的 tool_use，说明数据不完整
        return !pendingToolUses.isEmpty();
    }

    /**
     * 列出所有已存在的会话 ID。
     */
    public List<String> listSessions() {
        return store.listIds();
    }

    // ============================== 与 agent 的桥接 ==============================

    /**
     * 把历史消息回放到 agent 的 messageParams。
     * <p>由 agent 在 run 启动时调用，恢复上下文。
     */
    public void populate(List<MessageParam> out) {
        for (SessionMessage sm : sessionData.getMessages()) {
            out.add(converter.toMessageParam(sm));
        }
    }

    /**
     * 每当 agent 追加一条新消息时调用：转成 {@link SessionMessage} 并落盘。
     */
    public void onMessageAppended(MessageParam param) {
        sessionData.getMessages().add(converter.toSessionMessage(param));
        sessionData.setUpdatedAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
        persist();
    }

    /**
     * 每次调用 LLM 后记录 token 使用情况。
     */
    public void recordUsage(Usage usage) {
        if (usage == null) {
            return;
        }
        TokenUsage tokenUsage = TokenUsage.builder()
                .inputTokens(usage.inputTokens())
                .outputTokens(usage.outputTokens())
                .cacheReadTokens(usage.cacheReadInputTokens().orElse(null))
                .cacheCreationTokens(usage.cacheCreationInputTokens().orElse(null))
                .timestamp(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        sessionData.getUsage().add(tokenUsage);
        persist();
    }

    /**
     * 记录压缩操作。
     *
     * @param record 压缩记录
     */
    public void recordTranscript(TranscriptRecord record) {
        if (record == null) {
            return;
        }
        if (sessionData.getTranscripts() == null) {
            sessionData.setTranscripts(new ArrayList<>());
        }
        sessionData.getTranscripts().add(record);
        sessionData.setUpdatedAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
        persist();
    }

    /**
     * 当前消息数量。
     */
    public int historySize() {
        return sessionData.getMessages().size();
    }

    public String getSessionId() {
        return sessionId;
    }

    // ============================== 内部 ==============================

    private void persist() {
        if (sessionId == null) {
            return;
        }
        store.save(sessionId, sessionData);
    }

    // ============================== Token 统计 ==============================

    /**
     * 本次会话的总 token 消耗（input + output）。
     */
    public long getTotalTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(TokenUsage::getTotalTokens)
                .sum();
    }

    /**
     * 本次会话的输入 token 总和。
     */
    public long getInputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getInputTokens() != null ? u.getInputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的输出 token 总和。
     */
    public long getOutputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getOutputTokens() != null ? u.getOutputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中 token 总和。
     */
    public long getCacheReadTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheReadTokens() != null ? u.getCacheReadTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存创建 token 总和。
     */
    public long getCacheCreationTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheCreationTokens() != null ? u.getCacheCreationTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中率（0-1）。
     * <p>注：Anthropic API 的 {@code input_tokens} 与 {@code cache_read_input_tokens}
     * 是独立统计，后者是额外从 prompt cache 读取的 token 数。
     */
    public double getCacheHitRate() {
        long cached = getCacheReadTokens();
        long input = getInputTokens();
        long totalInput = cached + input;
        if (totalInput == 0) {
            return 0.0;
        }
        return (double) cached / totalInput;
    }

    /**
     * 本次会话的 LLM 调用次数。
     */
    public int getCallCount() {
        return sessionData.getUsage().size();
    }

    /**
     * 获取本次会话的 token 使用明细（只读）。
     */
    public List<TokenUsage> getUsageList() {
        return new ArrayList<>(sessionData.getUsage());
    }

    /**
     * 获取本次会话的压缩历史记录（只读）。
     */
    public List<TranscriptRecord> getTranscripts() {
        if (sessionData.getTranscripts() == null) {
            return new ArrayList<>();
        }
        return new ArrayList<>(sessionData.getTranscripts());
    }

    /**
     * 打印本次会话的 token 统计摘要。
     */
    public void printSummary() {
        System.out.printf("\u001b[90m========== 会话 %s 的 token 统计 ==========\u001b[0m%n", sessionId);
        System.out.printf("\u001b[90m调用次数\u001b[0m: %d%n", getCallCount());
        System.out.printf("\u001b[90m输入 tokens\u001b[0m: %,d%n", getInputTokens());
        System.out.printf("\u001b[90m输出 tokens\u001b[0m: %,d%n", getOutputTokens());
        System.out.printf("\u001b[90m缓存命中 tokens\u001b[0m: %,d%n", getCacheReadTokens());
        System.out.printf("\u001b[90m缓存创建 tokens\u001b[0m: %,d%n", getCacheCreationTokens());
        System.out.printf("\u001b[90m总计 tokens\u001b[0m: %,d%n", getTotalTokens());
        if (getInputTokens() > 0) {
            System.out.printf("\u001b[90m缓存命中率\u001b[0m: %.1f%%%n", getCacheHitRate() * 100);
        }
        System.out.println();
    }

    private String generateId() {
        String time = LocalDateTime.now().format(ID_FMT);
        String rand = Integer.toHexString(ThreadLocalRandom.current().nextInt(0x1000, 0x10000));
        return time + "-" + rand;
    }
}

package com.hoppinzq.agent.command;

import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.tool.skill.SkillLoader;

import java.util.List;

/**
 * Agent 特殊命令处理器。
 * <p>处理以 {@code /} 开头的用户命令，不发送给 LLM。
 * <p>内置命令：
 * <ul>
 *   <li>{@code /stats} —— 打印当前会话的 token 统计</li>
 *   <li>{@code /usage} —— 打印每次 LLM 调用的 token 明细</li>
 *   <li>{@code /skills} —— 查询已加载的技能信息</li>
 *   <li>{@code /tokens} —— 显示当前上下文的 token 估算（调试工具）</li>
 *   <li>{@code /transcripts} —— 查看压缩历史记录</li>
 *   <li>{@code /exit} —— 退出程序并打印统计</li>
 * </ul>
 *
 * @author hoppinzq
 */
public class AgentCommandHandler {

    private final SessionManager sessionManager;
    private final SkillLoader skillLoader;
    private final Runnable tokensHandler;

    public AgentCommandHandler(SessionManager sessionManager, SkillLoader skillLoader, Runnable tokensHandler) {
        this.sessionManager = sessionManager;
        this.skillLoader = skillLoader;
        this.tokensHandler = tokensHandler;
    }

    /**
     * 判断输入是否为特殊命令。
     *
     * @param input 用户输入
     * @return 若以 {@code /} 开头返回 {@code true}
     */
    public boolean isCommand(String input) {
        return input != null && input.startsWith("/");
    }

    /**
     * 执行特殊命令。
     *
     * @param input 用户输入（以 {@code /} 开头）
     * @return 若命令已处理返回 {@code true}；若为未知命令返回 {@code false}
     */
    public boolean handleCommand(String input) {
        if (!isCommand(input)) {
            return false;
        }

        switch (input.toLowerCase()) {
            case "/stats":
                handleStats();
                return true;
            case "/usage":
                handleUsage();
                return true;
            case "/skills":
                handleSkills();
                return true;
            case "/tokens":
                handleTokens();
                return true;
            case "/transcripts":
                handleTranscripts();
                return true;
            case "/exit":
                handleExit();
                return true;
            default:
                System.out.println("\u001b[90m[提示] 未知命令: " + input + "\u001b[0m");
                System.out.println("\u001b[90m可用命令: /stats, /usage, /skills, /tokens, /transcripts, /exit\u001b[0m");
                return true;
        }
    }

    private void handleStats() {
        if (sessionManager != null) {
            sessionManager.printSummary();
        } else {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无统计数据\u001b[0m");
        }
    }

    private void handleUsage() {
        if (sessionManager == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无统计数据\u001b[0m");
            return;
        }
        var usageList = sessionManager.getUsageList();
        if (usageList.isEmpty()) {
            System.out.println("\u001b[90m[提示] 本次会话暂无 token 记录\u001b[0m");
            return;
        }

        System.out.println("\u001b[90m========== Token 使用明细 ==========\u001b[0m");
        long totalInput = 0, totalOutput = 0, totalCache = 0;
        int idx = 1;
        for (var u : usageList) {
            long input = u.getInputTokens() != null ? u.getInputTokens() : 0;
            long output = u.getOutputTokens() != null ? u.getOutputTokens() : 0;
            long cache = u.getCacheReadTokens() != null ? u.getCacheReadTokens() : 0;
            totalInput += input;
            totalOutput += output;
            totalCache += cache;

            String time = u.getTimestamp() != null ? u.getTimestamp().substring(11, 19) : "--:--:--";
            System.out.printf("\u001b[90m[%d]\u001b[0m %s  输入:\u001b[90m%d\u001b[0m  输出:\u001b[90m%d\u001b[0m  缓存:\u001b[90m%d\u001b[0m%n",
                    idx++, time, input, output, cache);
        }
        System.out.println("\u001b[90m==================================\u001b[0m");
        System.out.printf("\u001b[90m总计\u001b[0m: 输入:\u001b[90m%d\u001b[0m  输出:\u001b[90m%d\u001b[0m  缓存:\u001b[90m%d\u001b[0m%n",
                totalInput, totalOutput, totalCache);
    }

    private void handleExit() {
        if (sessionManager != null) {
            sessionManager.printSummary();
        }
        System.out.println("再见！");
        System.exit(0);
    }

    private void handleSkills() {
        if (skillLoader == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用技能加载器，无技能信息\u001b[0m");
            return;
        }

        List<String> availableSkills = skillLoader.getAvailableSkills();
        System.out.println("=== 技能加载智能体 ===");
        System.out.println("已加载技能数量: " + availableSkills.size());
        System.out.println("可用技能: " + String.join(", ", availableSkills));
        System.out.println();
    }

    private void handleTranscripts() {
        if (sessionManager == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无压缩记录\u001b[0m");
            return;
        }

        var transcripts = sessionManager.getTranscripts();
        if (transcripts == null || transcripts.isEmpty()) {
            System.out.println("\u001b[90m[提示] 本次会话暂无压缩记录\u001b[0m");
            return;
        }

        System.out.println("\u001b[90m========== 压缩历史记录 ==========\u001b[0m");
        int idx = 1;
        for (var t : transcripts) {
            System.out.printf("\u001b[90m[%d]\u001b[0m %s  原因:\u001b[90m%s\u001b[0m  消息数:\u001b[90m%d\u001b[0m  Tokens:\u001b[90m%d\u001b[0m%n",
                    idx++, t.getTimestamp(), t.getReason(), t.getMessageCount(), t.getEstimatedTokens());
            if (t.getSummary() != null && !t.getSummary().isEmpty()) {
                System.out.printf("\u001b[90m摘要:\u001b[0m %s%n", t.getSummary().substring(0, Math.min(100, t.getSummary().length())));
                if (t.getSummary().length() > 100) {
                    System.out.println("...");
                }
            }
            System.out.println();
        }
    }

    private void handleTokens() {
        if (tokensHandler != null) {
            tokensHandler.run();
        } else {
            System.out.println("\u001b[90m[提示] 本会话未启用 token 统计功能\u001b[0m");
        }
    }
}

package com.hoppinzq.agent.tool.compact;

import com.anthropic.client.AnthropicClient;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.session.TranscriptRecord;
import lombok.extern.slf4j.Slf4j;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static com.hoppinzq.agent.constant.AIConstants.*;

/**
 * 上下文压缩器 - 四层压缩策略
 *
 * 压缩流程（参考Python s08设计）：
 * - L1: snip_compact      — 裁掉中间消息（消息数 > 50）
 * - L2: micro_compact     — 旧tool_result替换为占位符（保留最近3条）
 * - L3: tool_result_budget — 持久化大输出到磁盘（单次消息 > 30KB）
 * - L4: auto_compact      — LLM完整摘要（token超阈值）
 * - Emergency: reactive_compact — API返回prompt_too_long时触发
 *
 * 核心原则：cheap first, expensive last
 * 执行顺序：budget → snip → micro → auto
 *
 * @author hoppinzq
 */
@Slf4j
public class ContextCompactor {
    private final AnthropicClient client;
    private final String model;
    private final ObjectMapper mapper = new ObjectMapper();
    private final SessionManager sessionManager;

    public ContextCompactor(AnthropicClient client, String model, SessionManager sessionManager) {
        this.client = client;
        this.model = model;
        this.sessionManager = sessionManager;
    }

    /**
     * 兼容旧版本构造函数（不使用 SessionManager）
     */
    public ContextCompactor(AnthropicClient client, String model) {
        this(client, model, null);
    }

    // ============================== L1: snip_compact ==============================
    /**
     * L1: snip_compact — 裁掉中间消息（消息数超过50条时）
     *
     * 功能说明：
     * - 保留头部 KEEP_HEAD 条消息（初始上下文）
     * - 保留尾部消息（当前工作）
     * - 中间全部裁掉，替换为占位符
     * - 特殊处理：不能把 assistant(tool_use) 和后面的 user(tool_result) 拆开
     *
     * 执行时机：
     * - 每次LLM调用前检查消息数
     * - 当消息数 > MAX_MESSAGES 时触发
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> snipCompact(List<MessageParam> messages) {
        if (messages.size() <= MAX_MESSAGES) {
            return messages;
        }

        // 计算保留的头部和尾部
        int headEnd = KEEP_HEAD;
        int tailStart = messages.size() - (MAX_MESSAGES - KEEP_HEAD);

        // 边界条件1：不能把 assistant(tool_use) 和后面的 user(tool_result) 拆开
        if (headEnd > 0 && _messageHasToolUse(messages.get(headEnd - 1))) {
            while (headEnd < messages.size() && _isToolResultMessage(messages.get(headEnd))) {
                headEnd++;
            }
        }

        // 边界条件2：尾部起点也不能拆开 tool_use 和 tool_result
        if (tailStart > 0 && tailStart < messages.size()
                && _isToolResultMessage(messages.get(tailStart))
                && _messageHasToolUse(messages.get(tailStart - 1))) {
            tailStart--;
        }

        // 如果边界处理后头尾重叠，返回原消息列表
        if (headEnd >= tailStart) {
            return messages;
        }

        int snipped = tailStart - headEnd;

        // 构建压缩后的消息列表：头部 + 占位符 + 尾部
        List<MessageParam> newMessages = new ArrayList<>(messages.subList(0, headEnd));
        newMessages.add(MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content("[已省略 " + snipped + " 条对话历史消息]")
                .build());
        newMessages.addAll(messages.subList(tailStart, messages.size()));

        System.out.printf("\u001b[95m[snip compact]\u001b[0m 裁掉 %d 条消息（保留头部 %d 条）%n",
                snipped, KEEP_HEAD);

        return newMessages;
    }

    // ============================== L3: tool_result_budget ==============================
    /**
     * L3: tool_result_budget — 持久化大输出到磁盘
     *
     * 功能说明：
     * - 检查最后一条消息中的所有 tool_result
     * - 如果总字节数超过 MAX_BYTES_PER_MESSAGE，则持久化大的结果
     * - 按大小排序，优先持久化最大的结果
     * - 将持久化的结果替换为占位符，包含文件路径和预览
     *
     * 执行时机：
     * - 每次 tool_result 追加后检查
     * - 在 snip_compact 和 micro_compact 之后执行
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> toolResultBudget(List<MessageParam> messages) {
        if (messages.isEmpty()) {
            return messages;
        }

        // 获取最后一条消息
        MessageParam last = messages.get(messages.size() - 1);

        // 检查是否是用户消息且包含 tool_result
        if (!_isToolResultMessage(last)) {
            return messages;
        }

        // 收集所有 tool_result 块
        List<ToolResultInfo> toolResults = new ArrayList<>();
        if (last.content().isBlockParams()) {
            List<ContentBlockParam> contents = last.content().asBlockParams();
            for (int i = 0; i < contents.size(); i++) {
                ContentBlockParam block = contents.get(i);
                if (block.isToolResult()) {
                    toolResults.add(new ToolResultInfo(messages.size() - 1, i, block.toolResult().get()));
                }
            }
        }

        // 计算总字节数
        long totalBytes = 0;
        for (ToolResultInfo info : toolResults) {
            totalBytes += _getContentLength(info.result());
        }

        if (totalBytes <= MAX_BYTES_PER_MESSAGE) {
            return messages;
        }

        // 按大小排序（大到小）
        toolResults.sort((a, b) -> Long.compare(_getContentLength(b.result()), _getContentLength(a.result())));

        // 创建新的消息列表（复制）
        List<MessageParam> newMessages = new ArrayList<>(messages);
        MessageParam newLast = last;

        // 需要重建消息
        boolean needRebuild = true;
        List<ContentBlockParam> newBlocks = new ArrayList<>();

        // 处理每个 tool_result
        long currentTotal = totalBytes;
        for (ToolResultInfo info : toolResults) {
            if (currentTotal <= MAX_BYTES_PER_MESSAGE) {
                // 已经降到阈值以下，直接保留原始块
                if (last.content().isBlockParams()) {
                    newBlocks.add(last.content().asBlockParams().get(info.partIdx()));
                }
                break;
            }

            ToolResultBlockParam result = info.result();
            long contentLength = _getContentLength(result);

            if (contentLength <= PERSIST_THRESHOLD) {
                // 小于持久化阈值，保留原始内容
                if (last.content().isBlockParams()) {
                    newBlocks.add(last.content().asBlockParams().get(info.partIdx()));
                }
                continue;
            }

            // 持久化到磁盘
            String originalContent = _extractContentString(result);
            String persistedContent = _persistLargeOutput(result.toolUseId(), originalContent);

            // 创建替换的占位符块
            ToolResultBlockParam newResult = ToolResultBlockParam.builder()
                    .toolUseId(result.toolUseId())
                    .content(persistedContent)
                    .isError(false)
                    .build();

            newBlocks.add(ContentBlockParam.ofToolResult(newResult));

            // 更新总字节数
            currentTotal = currentTotal - contentLength + persistedContent.length();
        }

        // 重建最后一条消息
        if (needRebuild && !newBlocks.isEmpty()) {
            MessageParam.Content newContent = MessageParam.Content.ofBlockParams(newBlocks);
            newMessages.set(newMessages.size() - 1, MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(newContent)
                    .build());
        }

        System.out.printf("\u001b[95m[budget compact]\u001b[0m 持久化 %d 个大工具结果%n",
                toolResults.size());

        return newMessages;
    }

    // ============================== Emergency: reactive_compact ==============================
    /**
     * 紧急压缩 - 当API返回prompt_too_long时触发
     *
     * 功能说明：
     * - 保存完整对话记录到磁盘
     * - 生成对话摘要
     * - 保留首条用户消息 + 最近 KEEP_RECENT 条消息
     * - 中间用摘要替换
     *
     * 执行时机：
     * - API返回prompt_too_long错误时
     * - 作为最后的紧急手段
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> reactiveCompact(List<MessageParam> messages) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);

        try {
            // 步骤1：保存完整对话记录
            String transcriptPath = _saveTranscriptToDisk(messages);

            // 步骤2：生成摘要
            String summary = _generateSummary(messages);

            // 步骤3：构建压缩后的消息列表
            List<MessageParam> newMessages = new ArrayList<>();

            // 保留首条用户消息（如果存在）
            if (!messages.isEmpty()) {
                MessageParam first = messages.get(0);
                String roleStr = first._role().toString();
                if (roleStr.contains("user") || roleStr.contains("USER")) {
                    newMessages.add(first);
                }
            }

            // 添加摘要消息
            newMessages.add(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content("[紧急压缩以释放上下文]\n\n完整记录: " + transcriptPath + "\n\n" + summary)
                    .build());

            // 保留最近 KEEP_RECENT 条消息
            int tailStart = Math.max(0, messages.size() - KEEP_RECENT);

            // 边界条件：不能拆开 tool_use 和 tool_result
            if (tailStart > 0 && tailStart < messages.size()
                    && _isToolResultMessage(messages.get(tailStart))
                    && _messageHasToolUse(messages.get(tailStart - 1))) {
                tailStart--;
            }

            newMessages.addAll(messages.subList(tailStart, messages.size()));

            System.out.printf("\u001b[95m[reactive compact]\u001b[0m 保留首条 + 最近 %d 条，省略中间 %d 条%n",
                    KEEP_RECENT, messages.size() - newMessages.size());

            return newMessages;

        } catch (Exception e) {
            System.err.println("紧急压缩失败: " + e.getMessage());
            // 失败时返回原始消息列表
            return messages;
        }
    }

    // ============================== 辅助方法 ==============================

    /**
     * 判断消息是否包含 tool_use
     */
    private boolean _messageHasToolUse(MessageParam msg) {
        String roleStr = msg._role().toString();
        if (!roleStr.contains("assistant") && !roleStr.contains("ASSISTANT")) {
            return false;
        }

        if (!msg.content().isBlockParams()) {
            return false;
        }

        for (ContentBlockParam block : msg.content().asBlockParams()) {
            if (block.isToolUse()) {
                return true;
            }
        }

        return false;
    }

    /**
     * 判断消息是否包含 tool_result
     */
    private boolean _isToolResultMessage(MessageParam msg) {
        String roleStr = msg._role().toString();
        if (!roleStr.contains("user") && !roleStr.contains("USER")) {
            return false;
        }

        if (!msg.content().isBlockParams()) {
            return false;
        }

        for (ContentBlockParam block : msg.content().asBlockParams()) {
            if (block.isToolResult()) {
                return true;
            }
        }

        return false;
    }

    /**
     * 获取 tool_result 的内容长度
     */
    private long _getContentLength(ToolResultBlockParam result) {
        return _extractContentString(result).length();
    }

    /**
     * 从 ToolResultBlockParam 中提取内容字符串
     */
    private String _extractContentString(ToolResultBlockParam result) {
        // content() 返回 Optional<ToolResultBlockParam.Content>
        // 直接使用 toString() 获取内容字符串
        if (result.content().isPresent()) {
            Object content = result.content().get();
            // 尝试转换为字符串
            if (content instanceof String) {
                return (String) content;
            }
            // 其他类型，转换为字符串
            return content.toString();
        }
        return "";
    }

    /**
     * 持久化大输出到磁盘
     */
    private String _persistLargeOutput(String toolUseId, String output) {
        try {
            // 创建 tool-results 目录
            Path toolResultsDir = Paths.get(ROOT, ".task_outputs", "tool-results");
            Files.createDirectories(toolResultsDir);

            // 保存到文件
            Path filePath = toolResultsDir.resolve(toolUseId + ".txt");
            if (!Files.exists(filePath)) {
                Files.write(filePath, output.getBytes());
            }

            // 返回占位符
            String preview = output.length() > 2000 ? output.substring(0, 2000) : output;
            return String.format(
                    "<persisted-output>\n完整输出: %s\n预览:\n%s\n</persisted-output>",
                    filePath, preview
            );
        } catch (IOException e) {
            System.err.println("持久化工具结果失败: " + e.getMessage());
            return "[工具结果持久化失败: " + e.getMessage() + "]";
        }
    }

    /**
     * 保存对话记录到磁盘
     */
    private String _saveTranscriptToDisk(List<MessageParam> messages) throws IOException {
        Path transcriptDir = Paths.get(ROOT, ".transcripts");
        Files.createDirectories(transcriptDir);

        String timestamp = String.valueOf(System.currentTimeMillis());
        Path filePath = transcriptDir.resolve("transcript_" + timestamp + ".jsonl");

        List<String> lines = new ArrayList<>();
        for (MessageParam msg : messages) {
            lines.add(mapper.writeValueAsString(msg));
        }
        Files.write(filePath, lines);

        return filePath.toString();
    }

    /**
     * 生成对话摘要
     */
    private String _generateSummary(List<MessageParam> messages) {
        try {
            String conversationText = mapper.writeValueAsString(messages);
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            String prompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                    "1) 已完成的工作内容\n" +
                    "2) 当前状态\n" +
                    "3) 做出的关键决策\n" +
                    "4) 剩余工作\n" +
                    "5) 用户约束\n" +
                    "请简洁明了，但保留关键细节。\n\n" + conversationText;

            Message response = client.messages().create(MessageCreateParams.builder()
                    .model(model)
                    .messages(List.of(MessageParam.builder()
                            .role(MessageParam.Role.USER)
                            .content(prompt)
                            .build()))
                    .maxTokens(2000)
                    .build());

            return response.content().stream()
                    .filter(c -> c.isText())
                    .map(c -> c.text().map(TextBlock::text).orElse(""))
                    .collect(Collectors.joining("\n"));
        } catch (Exception e) {
            return "[摘要生成失败: " + e.getMessage() + "]";
        }
    }

    // ============================== 原有方法 ==============================

    /**
     * L2: micro_compact — 旧 tool_result 替换为占位符（保留最近3条）
     *
     * 功能说明：
     * - 遍历所有消息，收集工具调用和工具结果的位置信息
     * - 将旧的工具执行结果替换为简洁的占位符（如"[已执行: read_file]"）
     * - 保留最近KEEP_RECENT个工具结果不变，确保最近的工作上下文完整
     *
     * 执行时机：
     * - 每次调用LLM API前自动执行
     * - 在 snip_compact 和 tool_result_budget 之后执行
     * - 静默执行，对用户透明
     * - 高频执行以控制上下文大小
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表
     */
    public List<MessageParam> microCompact(List<MessageParam> messages) {
        // 【阶段1：信息收集】
        // 收集所有工具结果的位置信息（消息索引、内容块索引、结果数据）
        List<ToolResultInfo> toolResults = new ArrayList<>();

        // 建立工具ID到工具名称的映射，用于后续生成占位符
        Map<String, String> toolNameMap = new HashMap<>();

        // 遍历所有消息，构建工具结果索引和工具名称映射
        for (int i = 0; i < messages.size(); i++) {
            MessageParam msg = messages.get(i);
            try {
                // 兼容性处理：直接使用 _role() 获取原始值，避免 BigModel API 兼容性问题
                String roleStr = msg._role().toString();
                boolean isAssistant = roleStr.contains("assistant") || roleStr.contains("ASSISTANT");
                boolean isUser = roleStr.contains("user") || roleStr.contains("USER");
                MessageParam.Role role = isUser ? MessageParam.Role.USER : MessageParam.Role.ASSISTANT;

                if (isAssistant) {
                    // 处理助手消息：收集所有工具调用的ID和名称映射
                    if (msg.content().isBlockParams()) {
                        for (ContentBlockParam block : msg.content().asBlockParams()) {
                            if (block.isToolUse()) {
                                ToolUseBlockParam toolUse = block.toolUse().get();
                                toolNameMap.put(toolUse.id(), toolUse.name());
                            }
                        }
                    }
                } else if (isUser) {
                    // 处理用户消息：收集所有工具结果的位置信息
                    if (msg.content().isBlockParams()) {
                        List<ContentBlockParam> contents = msg.content().asBlockParams();
                        for (int j = 0; j < contents.size(); j++) {
                            ContentBlockParam block = contents.get(j);
                            if (block.isToolResult()) {
                                toolResults.add(new ToolResultInfo(i, j, block.toolResult().get()));
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // 处理消息时出错，打印错误信息并跳过该消息继续处理
                System.err.println("[微压缩] 处理第 " + i + " 条消息时出错: " + e.getMessage());
                e.printStackTrace();
                // 跳过此条消息，继续处理下一条
                continue;
            }
        }

        // 【阶段2：判断是否需要压缩】
        // 如果工具结果数量不超过保留数量，则无需压缩
        if (toolResults.size() <= KEEP_RECENT) {
            return messages;
        }

        // 【阶段3：执行压缩】
        List<MessageParam> newMessages = new ArrayList<>();
        int totalResults = toolResults.size();
        // 计算压缩阈值索引：在此索引之前的工具结果都将被替换为占位符
        int thresholdIndex = totalResults - KEEP_RECENT;

        // 当前遍历到的工具结果索引（从0开始递增）
        int currentResultIndex = 0;

        // 【阶段4：重建消息列表】
        for (MessageParam msg : messages) {
            // 直接使用 _role() 获取原始值，避免 BigModel API 兼容性问题
            String roleStr = msg._role().toString();
            boolean isUser = roleStr.contains("user") || roleStr.contains("USER");
            MessageParam.Role role = isUser ? MessageParam.Role.USER : MessageParam.Role.ASSISTANT;

            if (isUser) {
                if (!msg.content().isBlockParams()) {
                    newMessages.add(msg);
                    continue;
                }
                List<ContentBlockParam> oldBlocks = msg.content().asBlockParams();
                List<ContentBlockParam> newBlocks = new ArrayList<>();
                boolean changed = false;

                for (ContentBlockParam block : oldBlocks) {
                    if (block.isToolResult()) {
                        if (currentResultIndex < thresholdIndex) {
                            // 【压缩处理】将旧的工具执行结果替换为简洁的占位符
                            ToolResultBlockParam tr = block.toolResult().get();
                            String toolId = tr.toolUseId();
                            String toolName = toolNameMap.getOrDefault(toolId, "unknown");

                            // 占位符格式：[已执行: 工具名称]
                            // 这样可以保留工具调用历史，同时大幅减少token占用
                            newBlocks.add(ContentBlockParam.ofToolResult(
                                    ToolResultBlockParam.builder()
                                            .toolUseId(toolId)
                                            .content("[已执行: " + toolName + "]")
                                            .isError(false)
                                            .build()
                            ));
                            changed = true;
                        } else {
                            // 保留最近的工具结果（未被压缩的）
                            newBlocks.add(block);
                        }
                        currentResultIndex++;
                    } else {
                        // 非工具结果内容（如文本）直接保留
                        newBlocks.add(block);
                    }
                }

                if (changed) {
                    // 【消息重构】检测到内容被压缩，需要重新构建消息对象
                    // 将 List<ContentBlockParam> 转换为 Content 类型
                    if (!newBlocks.isEmpty()) {
                        MessageParam.Content content = MessageParam.Content.ofBlockParams(newBlocks);
                        newMessages.add(MessageParam.builder()
                                .role(role)
                                .content(content)
                                .build());
                    } else {
                        // 边界情况处理：如果压缩后newBlocks为空，保留原始消息
                        // 这种情况理论上不应发生，作为防御性编程处理
                        newMessages.add(msg);
                    }
                } else {
                    // 内容未改变，直接添加原消息
                    newMessages.add(msg);
                }
            } else {
                newMessages.add(msg);
            }
        }

        return newMessages;
    }

    /**
     * Layer 2: 自动压缩 - 完整对话压缩
     *
     * 功能说明：
     * - 将完整对话历史保存到 session 的 transcripts 或磁盘
     * - 请求LLM生成对话摘要（包含已完成的工作、当前状态、关键决策）
     * - 用摘要消息替换原始消息列表，实现上下文压缩
     *
     * 触发条件：
     * - 当估算的token数量超过 TOKEN_THRESHOLD 时自动触发
     *
     * @param messages 原始消息列表
     * @return 压缩后的消息列表（仅包含摘要消息）
     */
    public List<MessageParam> autoCompact(List<MessageParam> messages) {
        return autoCompact(messages, "auto");
    }

    /**
     * Layer 2/3: 完整对话压缩（可指定压缩原因）
     *
     * @param messages 原始消息列表
     * @param reason 压缩原因（auto/manual）
     * @return 压缩后的消息列表
     */
    public List<MessageParam> autoCompact(List<MessageParam> messages, String reason) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME);
        int estimatedTokens = estimateTokens(messages);
        int messageCount = messages.size();

        // 声明 transcriptPath 变量（方法级别）
        String transcriptPath = null;

        // 【步骤1】保存完整对话记录
        // 优先使用 SessionManager，如果不可用则保存到磁盘
        try {
            if (sessionManager != null) {
                // 使用 SessionManager 保存，将在步骤3中添加 transcript 记录
                transcriptPath = "会话 " + sessionManager.getSessionId() + " 的压缩记录";
                System.out.println("[准备压缩] 消息数: " + messageCount + ", 估算tokens: " + estimatedTokens);
            } else {
                // 保存到磁盘的 .transcripts/ 目录
                Path path = Paths.get(ROOT, ".transcripts");
                if (!Files.exists(path)) {
                    Files.createDirectories(path);
                }
                Path filePath = path.resolve("transcript_" + System.currentTimeMillis() + ".jsonl");
                List<String> lines = new ArrayList<>();
                for (MessageParam msg : messages) {
                    lines.add(mapper.writeValueAsString(msg));
                }
                Files.write(filePath, lines);
                transcriptPath = filePath.toString();
                System.out.println("[对话记录已保存: " + transcriptPath + "]");
            }

            // 【步骤2】生成对话摘要
            // 将消息列表转换为文本（限制在80000字符以内以避免超出API限制）
            String conversationText = messages.toString();
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            // 构建摘要提示词，要求LLM生成包含关键信息的简洁摘要
            String summaryPrompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                    "1) 已完成的工作内容\n" +
                    "2) 当前状态\n" +
                    "3) 做出的关键决策\n" +
                    "请简洁明了，但保留关键细节。\n\n" + conversationText;

            Message summaryMsg = client.messages().create(MessageCreateParams.builder()
                    .model(MODEL)
                    .messages(List.of(MessageParam.builder()
                            .role(MessageParam.Role.USER)
                            .content(summaryPrompt)
                            .build()))
                    .maxTokens(2000)
                    .build());

            String summary = summaryMsg.content().stream()
                    .filter(ContentBlock::isText)
                    .map(cb -> cb.text().get().text())
                    .collect(Collectors.joining());

            // 【步骤3】将压缩记录保存到 SessionManager（如果可用）
            if (sessionManager != null) {
                try {
                    // 创建 transcript 记录
                    TranscriptRecord record = TranscriptRecord.builder()
                            .timestamp(timestamp)
                            .messageCount(messageCount)
                            .estimatedTokens(estimatedTokens)
                            .summary(summary)
                            .reason(reason)
                            .build();
                    sessionManager.recordTranscript(record);
                    System.out.println("[压缩记录已保存到会话]");
                } catch (Exception e) {
                    System.err.println("[压缩记录保存失败] " + e.getMessage());
                }
            }

            // 【步骤4】构建压缩后的新消息列表
            // 包含两条消息：用户消息（告知对话已压缩并提供摘要）+ 助手确认消息
            List<MessageParam> newHistory = new ArrayList<>();
            newHistory.add(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content("[对话已压缩。完整记录: " + transcriptPath + "]\n\n" + summary)
                    .build());
            newHistory.add(MessageParam.builder()
                    .role(MessageParam.Role.ASSISTANT)
                    .content("收到。我已从摘要中获取了上下文。继续工作。")
                    .build());

            return newHistory;

        } catch (IOException e) {
            // 压缩失败时返回原始消息列表，确保对话不中断
            System.err.println("自动压缩时出错: " + e.getMessage());
            return messages;
        }
    }

    /**
     * 保存对话记录到磁盘
     *
     * 功能说明：
     * - 在 .transcripts 目录下创建以时间戳命名的 JSONL 文件
     * - 每条消息序列化为JSON后写入一行
     * - JSONL格式便于后续读取和分析
     *
     * 注意：虽然 SessionManager 已经存储会话数据，但这里保留磁盘备份
     * 因为 SessionManager 存储的是压缩后的消息，压缩前的完整对话需要额外保存
     *
     * @param messages 要保存的消息列表
     * @return 保存的文件路径，失败时返回错误标识
     */
    private String saveTranscript(List<MessageParam> messages) {
        try {
            // 创建transcript目录（如果不存在）
            Path transcriptDir = Paths.get(ROOT, ".transcripts");
            Files.createDirectories(transcriptDir);

            // 使用时间戳生成唯一文件名：transcript_<时间戳>.jsonl
            String timestamp = String.valueOf(System.currentTimeMillis());
            String transcriptPath = transcriptDir.resolve("transcript_" + timestamp + ".jsonl").toString();

            // 使用BufferedWriter逐行写入JSON格式的消息
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(transcriptPath))) {
                for (MessageParam msg : messages) {
                    String json = mapper.writeValueAsString(msg);
                    writer.write(json);
                    writer.newLine();
                }
            }

            log.info("[对话记录已保存: {}]", transcriptPath);
            return transcriptPath;
        } catch (IOException e) {
            log.error("保存对话记录失败", e);
            return "[对话记录保存失败]";
        }
    }

    /**
     * 请求LLM生成对话摘要
     *
     * 功能说明：
     * - 将消息列表序列化为文本（限制80000字符）
     * - 构建专门的摘要提示词
     * - 调用LLM API生成结构化的对话摘要
     *
     * @param messages 要摘要的消息列表
     * @return 生成的摘要文本，失败时返回错误信息
     */
    private String generateSummary(List<MessageParam> messages) {
        try {
            // 将消息序列化为JSON字符串（作为摘要的输入）
            String conversationText = mapper.writeValueAsString(messages);
            if (conversationText.length() > 80000) {
                conversationText = conversationText.substring(0, 80000);
            }

            // 构建中文摘要提示词
            String prompt = "请总结这段对话以保持上下文连贯性。需要包含：\n" +
                "1) 已完成的工作内容\n" +
                "2) 当前状态\n" +
                "3) 做出的关键决策\n" +
                "请简洁明了，但保留关键细节。\n\n" + conversationText;
            
            // 构建API请求参数
            MessageCreateParams params = MessageCreateParams.builder()
                .model(model)
                .messages(List.of(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(prompt)
                    .build()))
                .maxTokens(2000)  // 限制摘要长度为2000 tokens
                .build();

            // 调用LLM生成摘要
            Message response = client.messages().create(params);
            // 提取并拼接所有文本块
            return response.content().stream()
                .filter(c -> c.isText())
                .map(c -> c.text().map(TextBlock::text).orElse(""))
                .collect(Collectors.joining("\n"));
        } catch (Exception e) {
            log.error("生成摘要失败", e);
            return "[摘要生成失败: " + e.getMessage() + "]";
        }
    }

    /**
     * 估算消息列表的token数量
     *
     * 说明：
     * - 使用粗略估算方法：约4个字符 ≈ 1个token
     * - 将消息列表序列化为JSON后计算长度
     * - 用于判断是否需要触发自动压缩
     *
     * 注意：
     * - 这是简化估算，实际token数量可能有所不同
     * - 对于精确控制，应使用官方的tokenizer工具
     *
     * @param messages 要估算的消息列表
     * @return 估算的token数量
     */
    public static int estimateTokens(List<MessageParam> messages) {
        try {
            String json = OBJECT_MAPPER.writeValueAsString(messages);
            return json.length() / 4;
        } catch (Exception e) {
            // 序列化失败时返回0，表示无法估算
            return 0;
        }
    }

    /**
     * 工具结果信息记录
     *
     * 用于在微压缩过程中跟踪工具结果的位置信息：
     * - msgIdx: 消息在消息列表中的索引
     * - partIdx: 工具结果在消息内容块中的索引
     * - result: 工具执行结果的完整数据
     *
     * 通过这些信息，可以精确定位和替换需要压缩的工具结果
     */
    private static record ToolResultInfo(int msgIdx, int partIdx, ToolResultBlockParam result) {}
}

package com.hoppinzq.agent.session;

import com.anthropic.models.messages.MessageParam;
import com.anthropic.models.messages.Usage;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 会话编排器：维护当前 {@code sessionId} 与内存中的消息副本，
 * 在每条消息追加时自动持久化到 {@link SessionStore}。
 * <p>与 agent 解耦：agent 只需在添加消息时调用 {@link #onMessageAppended(MessageParam)}，
 * 启动时调用 {@link #populate(List)} 即可恢复历史。
 *
 * <h3>典型用法</h3>
 * <pre>{@code
 *   SessionManager sm = new SessionManager();
 *   if (args.length > 0 && sm.resume(args[0])) {
 *       System.out.println("已恢复会话 " + sm.getSessionId());
 *   } else {
 *       sm.startNew();
 *       System.out.println("新会话 " + sm.getSessionId());
 *   }
 *   agent.setSessionManager(sm);
 *   sm.populate(agent.getMessageParams());   // 由 ZQAgent.run 启动时自动调用
 *   agent.run();
 * }</pre>
 *
 * @author hoppinzq
 */
public class SessionManager {

    private static final DateTimeFormatter ID_FMT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

    private final SessionStore store;
    private final MessageConverter converter;
    private SessionData sessionData = SessionData.builder().build();
    private String sessionId;

    public SessionManager() {
        this(new SessionStore(), new MessageConverter());
    }

    public SessionManager(SessionStore store, MessageConverter converter) {
        this.store = store;
        this.converter = converter;
    }

    // ============================== 生命周期 ==============================

    /**
     * 创建一个新会话，生成形如 {@code yyyyMMdd-HHmmss-XXXX} 的 ID。
     */
    public String startNew() {
        this.sessionId = generateId();
        this.sessionData = SessionData.builder()
                .messages(new ArrayList<>())
                .usage(new ArrayList<>())
                .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        // 预先落盘一份空文件，便于 listIds 时就能看到
        persist();
        return this.sessionId;
    }

    /**
     * 恢复指定会话。
     *
     * @return 若会话存在且非空返回 {@code true}；否则返回 {@code false}（仍会以该 id 继续会话）
     */
    public boolean resume(String sessionId) {
        this.sessionId = sessionId;
        this.sessionData = store.load(sessionId);

        // 验证会话数据完整性：检查是否有未完成的 tool_use
        if (!this.sessionData.getMessages().isEmpty()) {
            boolean hasIncompleteToolUse = validateMessageIntegrity();
            if (hasIncompleteToolUse) {
                System.out.printf("\u001b[93m警告: 会话 %s 数据不完整，包含未完成的 tool_use，已清理\u001b[0m%n", sessionId);
                // 清理会话数据
                this.sessionData = SessionData.builder()
                        .messages(new ArrayList<>())
                        .usage(new ArrayList<>())
                        .createdAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                        .build();
                // 清空磁盘上的会话文件
                try {
                    store.save(sessionId, this.sessionData);
                } catch (Exception e) {
                    // 忽略保存失败
                }
                return false;
            }
        }

        boolean hasMessages = !this.sessionData.getMessages().isEmpty();
        // 若有历史 usage 数据，打印统计摘要
        if (hasMessages && !sessionData.getUsage().isEmpty()) {
            printSummary();
        }
        return hasMessages;
    }

    /**
     * 验证消息序列的完整性，检查是否有未完成的 tool_use。
     *
     * @return 如果发现未完成的 tool_use 返回 true，否则返回 false
     */
    private boolean validateMessageIntegrity() {
        Set<String> completedToolUses = new HashSet<>();
        Set<String> pendingToolUses = new HashSet<>();

        for (SessionMessage sm : sessionData.getMessages()) {
            if (sm.getBlocks() == null) {
                continue;
            }
            for (SessionBlock block : sm.getBlocks()) {
                if ("tool_use".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.add(toolUseId);
                    }
                } else if ("tool_result".equals(block.getType())) {
                    String toolUseId = block.getToolUseId();
                    if (toolUseId != null) {
                        pendingToolUses.remove(toolUseId);
                        completedToolUses.add(toolUseId);
                    }
                }
            }
        }

        // 如果还有未完成的 tool_use，说明数据不完整
        return !pendingToolUses.isEmpty();
    }

    /**
     * 列出所有已存在的会话 ID。
     */
    public List<String> listSessions() {
        return store.listIds();
    }

    // ============================== 与 agent 的桥接 ==============================

    /**
     * 把历史消息回放到 agent 的 messageParams。
     * <p>由 agent 在 run 启动时调用，恢复上下文。
     */
    public void populate(List<MessageParam> out) {
        for (SessionMessage sm : sessionData.getMessages()) {
            out.add(converter.toMessageParam(sm));
        }
    }

    /**
     * 每当 agent 追加一条新消息时调用：转成 {@link SessionMessage} 并落盘。
     */
    public void onMessageAppended(MessageParam param) {
        sessionData.getMessages().add(converter.toSessionMessage(param));
        sessionData.setUpdatedAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
        persist();
    }

    /**
     * 每次调用 LLM 后记录 token 使用情况。
     */
    public void recordUsage(Usage usage) {
        if (usage == null) {
            return;
        }
        TokenUsage tokenUsage = TokenUsage.builder()
                .inputTokens(usage.inputTokens())
                .outputTokens(usage.outputTokens())
                .cacheReadTokens(usage.cacheReadInputTokens().orElse(null))
                .cacheCreationTokens(usage.cacheCreationInputTokens().orElse(null))
                .timestamp(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .build();
        sessionData.getUsage().add(tokenUsage);
        persist();
    }

    /**
     * 记录压缩操作。
     *
     * @param record 压缩记录
     */
    public void recordTranscript(TranscriptRecord record) {
        if (record == null) {
            return;
        }
        if (sessionData.getTranscripts() == null) {
            sessionData.setTranscripts(new ArrayList<>());
        }
        sessionData.getTranscripts().add(record);
        sessionData.setUpdatedAt(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
        persist();
    }

    /**
     * 当前消息数量。
     */
    public int historySize() {
        return sessionData.getMessages().size();
    }

    public String getSessionId() {
        return sessionId;
    }

    // ============================== 内部 ==============================

    private void persist() {
        if (sessionId == null) {
            return;
        }
        store.save(sessionId, sessionData);
    }

    // ============================== Token 统计 ==============================

    /**
     * 本次会话的总 token 消耗（input + output）。
     */
    public long getTotalTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(TokenUsage::getTotalTokens)
                .sum();
    }

    /**
     * 本次会话的输入 token 总和。
     */
    public long getInputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getInputTokens() != null ? u.getInputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的输出 token 总和。
     */
    public long getOutputTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getOutputTokens() != null ? u.getOutputTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中 token 总和。
     */
    public long getCacheReadTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheReadTokens() != null ? u.getCacheReadTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存创建 token 总和。
     */
    public long getCacheCreationTokens() {
        return sessionData.getUsage().stream()
                .mapToLong(u -> u.getCacheCreationTokens() != null ? u.getCacheCreationTokens() : 0)
                .sum();
    }

    /**
     * 本次会话的缓存命中率（0-1）。
     * <p>注：Anthropic API 的 {@code input_tokens} 与 {@code cache_read_input_tokens}
     * 是独立统计，后者是额外从 prompt cache 读取的 token 数。
     */
    public double getCacheHitRate() {
        long cached = getCacheReadTokens();
        long input = getInputTokens();
        long totalInput = cached + input;
        if (totalInput == 0) {
            return 0.0;
        }
        return (double) cached / totalInput;
    }

    /**
     * 本次会话的 LLM 调用次数。
     */
    public int getCallCount() {
        return sessionData.getUsage().size();
    }

    /**
     * 获取本次会话的 token 使用明细（只读）。
     */
    public List<TokenUsage> getUsageList() {
        return new ArrayList<>(sessionData.getUsage());
    }

    /**
     * 获取本次会话的压缩历史记录（只读）。
     */
    public List<TranscriptRecord> getTranscripts() {
        if (sessionData.getTranscripts() == null) {
            return new ArrayList<>();
        }
        return new ArrayList<>(sessionData.getTranscripts());
    }

    /**
     * 打印本次会话的 token 统计摘要。
     */
    public void printSummary() {
        System.out.printf("\u001b[90m========== 会话 %s 的 token 统计 ==========\u001b[0m%n", sessionId);
        System.out.printf("\u001b[90m调用次数\u001b[0m: %d%n", getCallCount());
        System.out.printf("\u001b[90m输入 tokens\u001b[0m: %,d%n", getInputTokens());
        System.out.printf("\u001b[90m输出 tokens\u001b[0m: %,d%n", getOutputTokens());
        System.out.printf("\u001b[90m缓存命中 tokens\u001b[0m: %,d%n", getCacheReadTokens());
        System.out.printf("\u001b[90m缓存创建 tokens\u001b[0m: %,d%n", getCacheCreationTokens());
        System.out.printf("\u001b[90m总计 tokens\u001b[0m: %,d%n", getTotalTokens());
        if (getInputTokens() > 0) {
            System.out.printf("\u001b[90m缓存命中率\u001b[0m: %.1f%%%n", getCacheHitRate() * 100);
        }
        System.out.println();
    }

    private String generateId() {
        String time = LocalDateTime.now().format(ID_FMT);
        String rand = Integer.toHexString(ThreadLocalRandom.current().nextInt(0x1000, 0x10000));
        return time + "-" + rand;
    }
}

package com.hoppinzq.agent;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.*;
import com.hoppinzq.agent.base.ZQAgent;
import com.hoppinzq.agent.command.AgentCommandHandler;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.tool.compact.ContextCompactor;
import com.hoppinzq.agent.tool.ToolDefinition;
import com.hoppinzq.agent.tool.manager.TodoManager;
import com.hoppinzq.agent.tool.skill.SkillLoader;

import java.time.Duration;
import java.util.*;

import static com.hoppinzq.agent.constant.AIConstants.*;
import static com.hoppinzq.agent.tool.ToolDefinition.*;

/**
 * 上下文压缩智能体
 *
 * 四层压缩策略（参考Python s08设计）：
 * - L1: snip_compact      — 裁掉中间消息（消息数 > 50）
 * - L2: micro_compact     — 旧tool_result替换为占位符（保留最近3条）
 * - L3: tool_result_budget — 持久化大输出到磁盘（单次消息 > 30KB）
 * - L4: auto_compact      — LLM完整摘要（token超阈值）
 * - Emergency: reactive_compact — API返回prompt_too_long时触发
 *
 * 核心原则：cheap first, expensive last
 * 执行顺序：budget → snip → micro → auto
 *
 * @author hoppinzq
 */
public class Agent06 extends ZQAgent {
    public static ContextCompactor compactor;
    public static TodoManager todoManager;
    private int roundsSinceTodo = 0;
    private long lastTodoVersion = 0;
    public static SkillLoader skillLoader;

    /** 供 Tools.compact() 静态方法调用的压缩回调 */
    public static Runnable compactCallback;

    public Agent06(AnthropicClient client, String model, List<ToolDefinition> tools, ContextCompactor compactor, SkillLoader skillLoader, TodoManager todoManager) {
        super(client, model, tools);
        Agent06.compactor = compactor;
        Agent06.skillLoader = skillLoader;
        Agent06.todoManager = todoManager;
        this.lastTodoVersion = todoManager.getVersion();
        // 注册回调，让 Tools.compact 可以触发实例的 manualCompact
        Agent06.compactCallback = this::manualCompact;
    }

    /**
     * 重写createCommandHandler方法，添加tokens命令支持
     */
    @Override
    protected AgentCommandHandler createCommandHandler(SessionManager sessionManager, SkillLoader skillLoader) {
        // 创建一个Runnable来处理/tokens命令，显示当前token估算
        Runnable tokensHandler = () -> {
            showTokenStats();
        };

        return new AgentCommandHandler(sessionManager, skillLoader, tokensHandler);
    }

    /**
     * 显示当前 token 使用统计
     */
    private void showTokenStats() {
        int currentTokens = compactor.estimateTokens(this.messageParams);
        int currentMessages = this.messageParams.size();
        int threshold = TOKEN_THRESHOLD;

        System.out.println("\u001b[90m========== 当前 Token 统计 ==========\u001b[0m");
        System.out.println("当前消息数: " + currentMessages);
        System.out.println("估算 tokens: " + currentTokens);
        System.out.println("压缩阈值: " + threshold);
        System.out.println("使用率: " + String.format("%.1f%%", (currentTokens * 100.0 / threshold)));

        if (currentTokens >= threshold) {
            System.out.println("\u001b[91m状态: 已超过阈值，建议执行压缩\u001b[0m");
        } else if (currentTokens >= threshold * 0.8) {
            System.out.println("\u001b[93m状态: 接近阈值（80%），建议关注\u001b[0m");
        } else {
            System.out.println("\u001b[92m状态: 正常\u001b[0m");
        }
        System.out.println();
    }

    /**
     * 替换消息列表
     */
    private void replaceMessageParams(List<MessageParam> newParams) {
        this.messageParams.clear();
        this.messageParams.addAll(newParams);
    }

    /**
     * 手动压缩方法：由 compact 工具或命令触发
     *
     * 执行顺序（参考Python s08设计）：
     * 1. L3: tool_result_budget — 持久化大输出到磁盘（0 API调用，最便宜）
     * 2. L1: snip_compact — 裁掉中间消息（0 API调用，便宜）
     * 3. L2: micro_compact — 旧 tool_result 替换为占位符（0 API调用，便宜）
     * 4. L4: auto_compact — LLM 完整摘要（1 API调用，昂贵）
     *
     * 核心原则：cheap first, expensive last
     */
    private void manualCompact() {
        try {
            System.out.println("[开始手动压缩]");

            // 步骤1: L3 - tool_result_budget（持久化大输出）
            this.messageParams = compactor.toolResultBudget(new ArrayList<>(this.messageParams));

            // 步骤2: L1 - snip_compact（裁掉中间消息）
            this.messageParams = compactor.snipCompact(new ArrayList<>(this.messageParams));

            // 步骤3: L2 - micro_compact（旧 tool_result 替换为占位符）
            this.messageParams = compactor.microCompact(new ArrayList<>(this.messageParams));

            // 步骤4: 检查是否需要 L4 - auto_compact（LLM 完整摘要）
            if (ContextCompactor.estimateTokens(this.messageParams) > TOKEN_THRESHOLD) {
                System.out.println("[token 仍超阈值，执行 LLM 摘要压缩]");
                this.messageParams = compactor.autoCompact(new ArrayList<>(this.messageParams), "manual");
            }

            System.out.println("[压缩完成] 上下文已清理，下次对话将使用压缩后的上下文。");

        } catch (Exception e) {
            System.err.println("[压缩失败] " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * 重写chatMessage方法，实现四层压缩策略
     *
     * 压缩流程（参考Python s08设计）：
     * 1. L3（budget）：持久化大输出到磁盘（0 API调用）
     * 2. L1（snip）：裁掉中间消息（0 API调用）
     * 3. L2（micro）：旧 tool_result 替换为占位符（0 API调用）
     * 4. L4（auto）：当token估算超过阈值时，保存完整对话并生成摘要（1 API调用）
     *
     * 状态同步说明：
     * - ZQAgent将messageParams字段直接传递给此方法（引用传递）
     * - 压缩返回新列表
     * - 发生压缩时，需要同步更新ZQAgent的状态
     *
     * 核心原则：cheap first, expensive last
     *
     * @param messageParams 原始消息参数列表
     * @return LLM响应消息
     */
    @Override
    protected Message chatMessage(List<MessageParam> messageParams) {
        // 执行三层预处理（0 API调用，cheap first）
        // 执行顺序：budget → snip → micro（与Python s08一致）

        // 注意：messageParams 是引用传递，不能直接 clear() 后再使用
        // 需要先保存原始消息，然后逐步处理

        // L3: tool_result_budget — 持久化大输出
        List<MessageParam> working = new ArrayList<>(messageParams);
        working = compactor.toolResultBudget(working);

        // L1: snip_compact — 裁掉中间消息
        working = compactor.snipCompact(working);

        // L2: micro_compact — 旧 tool_result 替换为占位符
        working = compactor.microCompact(working);

        // 将处理后的消息复制回 messageParams
        messageParams.clear();
        messageParams.addAll(working);

        // L4: auto_compact — token仍超阈值时触发（1 API调用，expensive last）
        if (ContextCompactor.estimateTokens(messageParams) > TOKEN_THRESHOLD) {
            System.out.println("[自动 LLM 摘要压缩已触发]");
            List<MessageParam> compactedParams = compactor.autoCompact(new ArrayList<>(messageParams), "auto");

            // 【状态同步】替换 messageParams 并同步 session
            replaceMessageParams(compactedParams);
            return super.chatMessage(compactedParams);
        }

        // 使用（可能被压缩的）消息参数调用父类的chatMessage
        return super.chatMessage(messageParams);
    }

    /**
     * 重写onToolExecution方法，实现压缩策略和待办事项提醒
     *
     * 功能包括：
     * 1. 待办事项提醒：跟踪更新间隔，超过3回合未更新时提醒
     * 2. 执行完整的三层压缩（budget → snip → micro → auto）
     *
     * @param toolResults 工具执行结果列表
     */
    @Override
    protected void onToolExecution(List<ContentBlockParam> toolResults) {
        // ========== 待办事项提醒逻辑 ==========
        long currentVersion = todoManager.getVersion();
        if (currentVersion > lastTodoVersion) {
            // 检测到待办列表已更新，重置计数器
            roundsSinceTodo = 0;
            lastTodoVersion = currentVersion;
        } else {
            // 待办列表未更新，增加回合计数
            roundsSinceTodo++;
        }

        // 如果超过3个回合未更新待办，添加提醒消息
        if (roundsSinceTodo >= 3) {
            String reminder = String.format("<reminder>\n您已经 %d 个回合没有更新待办事项列表了。请更新列表以反映当前进度。\n</reminder>", roundsSinceTodo);
            toolResults.add(ContentBlockParam.ofText(TextBlockParam.builder()
                    .text(reminder)
                    .build()));
        }

        // ========== 四层压缩策略 ==========
        // 执行顺序：budget → snip → micro → auto（与Python s08一致）

        // 注意：messageParams 是引用传递，不能直接 clear() 后再使用
        // 需要先保存原始消息，然后逐步处理

        // L3: tool_result_budget — 持久化大输出
        List<MessageParam> working = new ArrayList<>(messageParams);
        working = compactor.toolResultBudget(working);

        // L1: snip_compact — 裁掉中间消息
        working = compactor.snipCompact(working);

        // L2: micro_compact — 旧 tool_result 替换为占位符
        working = compactor.microCompact(working);

        // 将处理后的消息复制回 messageParams
        messageParams.clear();
        messageParams.addAll(working);

        // L4: auto_compact — token仍超阈值时触发
        if (compactor.estimateTokens(messageParams) > TOKEN_THRESHOLD) {
            System.out.println("[自动 LLM 摘要压缩已触发]");
            List<MessageParam> compressed = compactor.autoCompact(new ArrayList<>(messageParams), "auto");
            replaceMessageParams(compressed);
        }
    }

    /**
     * 生成Agent06的系统提示词
     * 
     * @param root 工作目录
     * @param skillDescriptions 技能描述
     * @return 完整的系统提示词
     */
    public static String generateSystemPrompt(String root, String skillDescriptions) {
        return String.format(
                "你是一个具有上下文压缩能力的编程智能体，工作在目录: %s\n\n" +
                "核心能力：\n" +
                "- 使用工具读写文件、编辑代码、执行命令、搜索内容\n" +
                "- 通过 todo 工具管理任务列表，追踪复杂任务进度\n" +
                "- 在对话过程中自动压缩上下文，支持长时间工作\n" +
                "- 加载专业技能以应对特定领域的任务\n\n" +
                "工作指南：\n" +
                "1. 优先使用工具解决任务，而非仅提供建议\n" +
                "2. 在处理复杂或不熟悉的主题时，使用 load_skill 工具获取专业知识\n" +
                "3. 使用 todo 工具将大任务分解为小步骤，逐个完成\n" +
                "4. 当上下文过大时，系统会自动压缩历史对话，保持连贯性\n\n" +
                "可用的技能：\n%s",
                root,
                skillDescriptions
        );
    }

    public static void main(String[] args) {
        AnthropicClient client = AnthropicOkHttpClient.builder()
            .apiKey(API_KEY)
            .baseUrl(BASE_URL)
            .timeout(Duration.ofSeconds(TIMEOUT))
            .maxRetries(MAX_RETRIES)
            .build();

        // 创建技能加载器
        skillLoader = new SkillLoader();
        todoManager = new TodoManager();

        // 先创建 SessionManager
        SessionManager sessionManager = bootstrapSession(args);

        // 创建 ContextCompactor，传入 SessionManager
        compactor = new ContextCompactor(client, MODEL, sessionManager);

        List<ToolDefinition> tools = new ArrayList<>();
        tools.add(BashDefinition);
        tools.add(ReadFileDefinition);
        tools.add(EditFileDefinition);
        tools.add(WriteFileDefinition);
        tools.add(GlobDefinition);
        tools.add(ContentSearchDefinition);
        tools.add(SubAgentDefinition);
        tools.add(TodoDefinition);
        tools.add(SkillsDefinition);

        tools.add(ContentCompactDefinition);
        Agent06 agent = new Agent06(client, MODEL, tools, compactor, skillLoader, todoManager);

        // 使用新方法构建系统提示词
        String systemPrompt = generateSystemPrompt(ROOT, skillLoader.getDescriptions());
        agent.setSystemPrompt(systemPrompt);

        System.out.println("=== 上下文压缩智能体 ===");
        System.out.println("四层压缩策略（参考Python s08设计）：");
        System.out.println("  L1 snip_compact: 最大消息数 = " + MAX_MESSAGES + ", 保留头部 = " + KEEP_HEAD);
        System.out.println("  L2 micro_compact: 保留最近工具结果数 = " + KEEP_RECENT);
        System.out.println("  L3 budget: 持久化阈值 = " + (PERSIST_THRESHOLD / 1024) + "KB, 单次消息最大 = " + (MAX_BYTES_PER_MESSAGE / 1024) + "KB");
        System.out.println("  L4 auto_compact: token阈值 = " + CONTEXT_LIMIT);
        System.out.println();

        agent.setSessionManager(sessionManager, skillLoader);
        try {
            agent.run();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * 启动会话：若命令行传入了 sessionId 则尝试恢复；否则交互式询问。
     * <ul>
     *   <li>{@code java AgentXX <sessionId>} —— 直接恢复指定会话</li>
     *   <li>无参启动 —— 列出已有会话，输入序号恢复或回车开新会话</li>
     * </ul>
     */
    private static SessionManager bootstrapSession(String[] args) {
        SessionManager sm = new SessionManager();
        if (args.length > 0 && !args[0].isBlank()) {
            boolean ok = sm.resume(args[0]);
            System.out.println(ok
                    ? "已恢复会话 " + args[0]
                    : "会话 " + args[0] + " 不存在或为空，将以该 ID 开始新会话");
            return sm;
        }
        Scanner sc = new Scanner(System.in);
        List<String> sessions = sm.listSessions();
        if (sessions.isEmpty()) {
            sm.startNew();
            System.out.println("新会话已创建: " + sm.getSessionId());
            return sm;
        }
        System.out.println("\n\033[95m========== 历史会话 ==========\033[0m");
        for (int i = 0; i < sessions.size(); i++) {
            System.out.printf("\033[95m%d\033[0m) %s%n", i + 1, sessions.get(i));
        }
        System.out.print("输入序号恢复对应会话，或直接回车开启新会话: ");
        String line = sc.nextLine().trim();
        if (line.isEmpty()) {
            sm.startNew();
            System.out.println("新会话已创建: " + sm.getSessionId());
            return sm;
        }
        try {
            int idx = Integer.parseInt(line) - 1;
            if (idx >= 0 && idx < sessions.size()) {
                String id = sessions.get(idx);
                sm.resume(id);
                System.out.println("已恢复会话: " + id);
                return sm;
            }
        } catch (NumberFormatException ignore) {
            // 用户可能直接输入了 sessionId
            if (sessions.contains(line)) {
                sm.resume(line);
                System.out.println("已恢复会话: " + line);
                return sm;
            }
        }
        sm.startNew();
        System.out.println("输入无效，已开启新会话: " + sm.getSessionId());
        return sm;
    }
}

