package com.hoppinzq.agent.command;

import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.tool.skill.SkillLoader;

import java.util.List;

/**
 * Agent 特殊命令处理器。
 * <p>处理以 {@code /} 开头的用户命令，不发送给 LLM。
 * <p>内置命令：
 * <ul>
 *   <li>{@code /stats} —— 打印当前会话的 token 统计</li>
 *   <li>{@code /usage} —— 打印每次 LLM 调用的 token 明细</li>
 *   <li>{@code /skills} —— 查询已加载的技能信息</li>
 *   <li>{@code /tokens} —— 显示当前上下文的 token 估算（调试工具）</li>
 *   <li>{@code /transcripts} —— 查看压缩历史记录</li>
 *   <li>{@code /exit} —— 退出程序并打印统计</li>
 * </ul>
 *
 * @author hoppinzq
 */
public class AgentCommandHandler {

    private final SessionManager sessionManager;
    private final SkillLoader skillLoader;
    private final Runnable tokensHandler;

    public AgentCommandHandler(SessionManager sessionManager, SkillLoader skillLoader, Runnable tokensHandler) {
        this.sessionManager = sessionManager;
        this.skillLoader = skillLoader;
        this.tokensHandler = tokensHandler;
    }

    /**
     * 判断输入是否为特殊命令。
     *
     * @param input 用户输入
     * @return 若以 {@code /} 开头返回 {@code true}
     */
    public boolean isCommand(String input) {
        return input != null && input.startsWith("/");
    }

    /**
     * 执行特殊命令。
     *
     * @param input 用户输入（以 {@code /} 开头）
     * @return 若命令已处理返回 {@code true}；若为未知命令返回 {@code false}
     */
    public boolean handleCommand(String input) {
        if (!isCommand(input)) {
            return false;
        }

        switch (input.toLowerCase()) {
            case "/stats":
                handleStats();
                return true;
            case "/usage":
                handleUsage();
                return true;
            case "/skills":
                handleSkills();
                return true;
            case "/tokens":
                handleTokens();
                return true;
            case "/transcripts":
                handleTranscripts();
                return true;
            case "/exit":
                handleExit();
                return true;
            default:
                System.out.println("\u001b[90m[提示] 未知命令: " + input + "\u001b[0m");
                System.out.println("\u001b[90m可用命令: /stats, /usage, /skills, /tokens, /transcripts, /exit\u001b[0m");
                return true;
        }
    }

    private void handleStats() {
        if (sessionManager != null) {
            sessionManager.printSummary();
        } else {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无统计数据\u001b[0m");
        }
    }

    private void handleUsage() {
        if (sessionManager == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无统计数据\u001b[0m");
            return;
        }
        var usageList = sessionManager.getUsageList();
        if (usageList.isEmpty()) {
            System.out.println("\u001b[90m[提示] 本次会话暂无 token 记录\u001b[0m");
            return;
        }

        System.out.println("\u001b[90m========== Token 使用明细 ==========\u001b[0m");
        long totalInput = 0, totalOutput = 0, totalCache = 0;
        int idx = 1;
        for (var u : usageList) {
            long input = u.getInputTokens() != null ? u.getInputTokens() : 0;
            long output = u.getOutputTokens() != null ? u.getOutputTokens() : 0;
            long cache = u.getCacheReadTokens() != null ? u.getCacheReadTokens() : 0;
            totalInput += input;
            totalOutput += output;
            totalCache += cache;

            String time = u.getTimestamp() != null ? u.getTimestamp().substring(11, 19) : "--:--:--";
            System.out.printf("\u001b[90m[%d]\u001b[0m %s  输入:\u001b[90m%d\u001b[0m  输出:\u001b[90m%d\u001b[0m  缓存:\u001b[90m%d\u001b[0m%n",
                    idx++, time, input, output, cache);
        }
        System.out.println("\u001b[90m==================================\u001b[0m");
        System.out.printf("\u001b[90m总计\u001b[0m: 输入:\u001b[90m%d\u001b[0m  输出:\u001b[90m%d\u001b[0m  缓存:\u001b[90m%d\u001b[0m%n",
                totalInput, totalOutput, totalCache);
    }

    private void handleExit() {
        if (sessionManager != null) {
            sessionManager.printSummary();
        }
        System.out.println("再见！");
        System.exit(0);
    }

    private void handleSkills() {
        if (skillLoader == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用技能加载器，无技能信息\u001b[0m");
            return;
        }

        List<String> availableSkills = skillLoader.getAvailableSkills();
        System.out.println("=== 技能加载智能体 ===");
        System.out.println("已加载技能数量: " + availableSkills.size());
        System.out.println("可用技能: " + String.join(", ", availableSkills));
        System.out.println();
    }

    private void handleTranscripts() {
        if (sessionManager == null) {
            System.out.println("\u001b[90m[提示] 本会话未启用 session 管理器，无压缩记录\u001b[0m");
            return;
        }

        var transcripts = sessionManager.getTranscripts();
        if (transcripts == null || transcripts.isEmpty()) {
            System.out.println("\u001b[90m[提示] 本次会话暂无压缩记录\u001b[0m");
            return;
        }

        System.out.println("\u001b[90m========== 压缩历史记录 ==========\u001b[0m");
        int idx = 1;
        for (var t : transcripts) {
            System.out.printf("\u001b[90m[%d]\u001b[0m %s  原因:\u001b[90m%s\u001b[0m  消息数:\u001b[90m%d\u001b[0m  Tokens:\u001b[90m%d\u001b[0m%n",
                    idx++, t.getTimestamp(), t.getReason(), t.getMessageCount(), t.getEstimatedTokens());
            if (t.getSummary() != null && !t.getSummary().isEmpty()) {
                System.out.printf("\u001b[90m摘要:\u001b[0m %s%n", t.getSummary().substring(0, Math.min(100, t.getSummary().length())));
                if (t.getSummary().length() > 100) {
                    System.out.println("...");
                }
            }
            System.out.println();
        }
    }

    private void handleTokens() {
        if (tokensHandler != null) {
            tokensHandler.run();
        } else {
            System.out.println("\u001b[90m[提示] 本会话未启用 token 统计功能\u001b[0m");
        }
    }
}

package com.hoppinzq.agent.tool;

