    /**
     * 手动压缩工具 - 触发完整压缩
     *
     * 功能说明：
     * - 通过回调立即执行压缩
     * - 压缩后的上下文会在下次 LLM 调用时生效
     * - 返回压缩确认消息
     *
     * 执行时机：LLM 主动调用 compact 工具时
     *
     * @param json 输入的 JSON 参数（包含可选的 focus 字段）
     * @return 压缩执行结果
     */
    public static String compact(String json) {
        // 通过回调立即执行压缩
        if (Agent06.compactCallback != null) {
            try {
                Agent06.compactCallback.run();
                return "压缩完成。上下文已清理，完整历史已保存到会话。下次对话将使用压缩后的上下文。";
            } catch (Exception e) {
                return "压缩失败: " + e.getMessage();
            }
        }
        return "压缩功能不可用：未初始化压缩回调。";
    }

    /**
     * 统计子字符串在主字符串中出现的次数
     * <p>
     * 特性：对空白字符进行归一化处理，将 \r\n 统一为 \n，将制表符转换为空格，
     * 并将每行内连续多个空格压缩为单个空格，这样可以匹配由于缩进格式不同（制表符vs空格）
     * 或换行符不同（\r\n vs \n）导致的视觉上相同但技术上不同的字符串。
     *
     * @param str 主字符串，如果为null则返回0
     * @param substr 要查找的子字符串，如果为null或空字符串则返回0
     * @return 子字符串在主字符串中出现的次数
     */
    private static int countOccurrences(String str, String substr) {
        if (str == null || substr == null || substr.isEmpty()) {
            return 0;
        }

        String normalizedStr = normalizeForReplace(str);
        String normalizedSubstr = normalizeForReplace(substr);

        int count = 0;
        int idx = 0;
        while ((idx = normalizedStr.indexOf(normalizedSubstr, idx)) != -1) {
            count++;
            idx += normalizedSubstr.length();
        }
        return count;
    }

    /**
     * 归一化字符串用于替换操作
     * <p>
     * 将 \r\n 统一为 \n，将制表符转换为4个空格（保持代码缩进结构）。
     * 这样可以匹配由于缩进格式不同（制表符vs空格）或换行符不同（\r\n vs \n）导致的视觉上相同但技术上不同的字符串。
     *
     * @param str 要归一化的字符串
     * @return 归一化后的字符串
     */
    private static String normalizeForReplace(String str) {
        if (str == null) {
            return null;
        }

        // 统一换行符：将 \r\n 和 \r 都转换为 \n
        String normalized = str.replace("\r\n", "\n").replace("\r", "\n");

        // 将制表符转换为4个空格（保持代码缩进结构）
        normalized = normalized.replace("\t", "    ");

        return normalized;
    }

    /**
     * 创建新文件并写入内容，如果父目录不存在则自动创建
     *
     * @param filePath 要创建的文件路径
     * @param content 要写入文件的内容
     * @return 返回操作结果字符串，包含成功创建的文件路径
     * @throws IOException 当文件创建或写入过程中发生I/O错误时抛出
     */
    private static String createNewFile(Path filePath, String content) throws IOException {
        if (AIConstants.LOG_ENABLE) {
            log.info("创建文件: {} ({} bytes)", filePath, content.length());
        }

        Path parent = filePath.getParent();
        if (parent != null && !Files.exists(parent)) {
            if (AIConstants.LOG_ENABLE) {
                log.info("创建文件夹: {}", parent);
            }
            Files.createDirectories(parent);
        }

        Files.write(filePath, content.getBytes(), StandardOpenOption.CREATE);

        if (AIConstants.LOG_ENABLE) {
            log.info("成功创建文件 {}", filePath);
        }

        return "成功创建文件 " + filePath;
    }
}

package com.hoppinzq.agent.session;

import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import static com.hoppinzq.agent.constant.AIConstants.OBJECT_MAPPER;

/**
 * 在 SDK 的 {@link MessageParam} 与可序列化 {@link SessionMessage} 之间双向转换。
 * <p>该类无状态、线程不安全（仅设计用于单线程 agent 循环）。
 *
 * @author hoppinzq
 */
public final class MessageConverter {

    private final ObjectMapper mapper;

    public MessageConverter() {
        this(OBJECT_MAPPER);
    }

    public MessageConverter(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    // ============================== MessageParam -> SessionMessage ==============================

    public SessionMessage toSessionMessage(MessageParam param) {
        SessionMessage.SessionMessageBuilder b = SessionMessage.builder()
                .role(roleString(param));
        MessageParam.Content content = param.content();
        if (content.isString()) {
            b.text(content.asString());
        } else if (content.isBlockParams()) {
            List<SessionBlock> blocks = new ArrayList<>();
            for (ContentBlockParam cbp : content.asBlockParams()) {
                blocks.add(toSessionBlock(cbp));
            }
            b.blocks(blocks);
        }
        return b.build();
    }

    private SessionBlock toSessionBlock(ContentBlockParam cbp) {
        if (cbp.isText()) {
            TextBlockParam t = cbp.asText();
            return SessionBlock.builder().type("text").text(t.text()).build();
        }
        if (cbp.isToolUse()) {
            ToolUseBlockParam tu = cbp.asToolUse();
            return SessionBlock.builder()
                    .type("tool_use")
                    .toolUseId(tu.id())
                    .toolName(tu.name())
                    .toolInputJson(inputToJsonString(tu))
                    .build();
        }
        if (cbp.isToolResult()) {
            ToolResultBlockParam tr = cbp.asToolResult();
            SessionBlock.SessionBlockBuilder b = SessionBlock.builder()
                    .type("tool_result")
                    .toolUseId(tr.toolUseId());
            Optional<String> str = tr.content().flatMap(ToolResultBlockParam.Content::string);
            str.ifPresent(b::toolResultContent);
            tr.isError().ifPresent(b::isError);
            return b.build();
        }
        // 其他块类型（image/thinking/...）退化为文本占位，避免丢失消息结构
        return SessionBlock.builder().type("text").text("[unsupported block]").build();
    }

    /**
     * 提取 ToolUseBlockParam 的 input 为 JSON 字符串。
     */
    private String inputToJsonString(ToolUseBlockParam tu) {
        try {
            // SDK 的 input() 返回 Input 对象，其底层为 additionalProperties Map<String, JsonValue>
            Map<String, JsonValue> map = tu.input()._additionalProperties();
            if (map == null || map.isEmpty()) {
                return "{}";
            }
            // 把 Map<String, JsonValue> 转为 ObjectNode；JsonValue 通过 SDK 自带的 convert 落到 JsonNode
            com.fasterxml.jackson.databind.node.ObjectNode root = mapper.createObjectNode();
            for (Map.Entry<String, JsonValue> e : map.entrySet()) {
                JsonNode child = e.getValue().convert(JsonNode.class);
                root.set(e.getKey(), child == null ? mapper.nullNode() : child);
            }
            return root.toString();
        } catch (Exception e) {
            return "{}";
        }
    }

    // ============================== SessionMessage -> MessageParam ==============================

    public MessageParam toMessageParam(SessionMessage sm) {
        MessageParam.Builder b = MessageParam.builder()
                .role(parseRole(sm.getRole()));
        if (sm.getText() != null) {
            b.content(sm.getText());
        } else if (sm.getBlocks() != null) {
            List<ContentBlockParam> cbps = new ArrayList<>();
            for (SessionBlock sb : sm.getBlocks()) {
                cbps.add(toContentBlockParam(sb));
            }
            b.content(MessageParam.Content.ofBlockParams(cbps));
        } else {
            // 兜底：空内容
            b.content("");
        }
        return b.build();
    }

    private ContentBlockParam toContentBlockParam(SessionBlock sb) {
        String type = sb.getType() == null ? "text" : sb.getType();
        switch (type) {
            case "tool_use":
                return ContentBlockParam.ofToolUse(buildToolUse(sb));
            case "tool_result":
                return ContentBlockParam.ofToolResult(buildToolResult(sb));
            case "text":
            default:
                return ContentBlockParam.ofText(
                        TextBlockParam.builder().text(sb.getText() == null ? "" : sb.getText()).build());
        }
    }

    private ToolUseBlockParam buildToolUse(SessionBlock sb) {
        ToolUseBlockParam.Builder b = ToolUseBlockParam.builder()
                .id(sb.getToolUseId())
                .name(sb.getToolName());
        ToolUseBlockParam.Input.Builder ib = ToolUseBlockParam.Input.builder();
        Map<String, JsonValue> map = parseInputMap(sb.getToolInputJson());
        if (!map.isEmpty()) {
            ib.putAllAdditionalProperties(map);
        }
        b.input(ib.build());
        return b.build();
    }

    private ToolResultBlockParam buildToolResult(SessionBlock sb) {
        ToolResultBlockParam.Builder b = ToolResultBlockParam.builder()
                .toolUseId(sb.getToolUseId());
        if (sb.getToolResultContent() != null) {
            b.content(sb.getToolResultContent());
        }
        if (sb.getIsError() != null) {
            b.isError(sb.getIsError());
        }
        return b.build();
    }

    /**
     * 将 JSON 字符串解析为 {@code Map<String, JsonValue>}。
     */
    private Map<String, JsonValue> parseInputMap(String json) {
        if (json == null || json.isBlank()) {
            return Map.of();
        }
        try {
            JsonNode node = mapper.readTree(json);
            if (!node.isObject()) {
                return Map.of();
            }
            java.util.HashMap<String, JsonValue> out = new java.util.HashMap<>();
            node.fields().forEachRemaining(e -> out.put(e.getKey(), JsonValue.fromJsonNode(e.getValue())));
            return out;
        } catch (Exception e) {
            return Map.of();
        }
    }

    private MessageParam.Role parseRole(String role) {
        if (role == null) {
            return MessageParam.Role.USER;
        }
        String r = role.toLowerCase();
        if ("assistant".equals(r)) {
            return MessageParam.Role.ASSISTANT;
        }
        return MessageParam.Role.USER;
    }

    /**
     * 安全读取 MessageParam 的 role 字符串。
     * <p>SDK 的 {@code param.role()} 会做严格校验，对来自 {@code message.toParam()} 的
     * 「未知但合法」消息会抛 {@code AnthropicInvalidDataException}。
     * 这里改走底层 {@code _role()} 的 JsonField，直接拿原始字符串。
     */
    private String roleString(MessageParam param) {
        return param._role().asString().orElse("user");
    }
}

package com.hoppinzq.agent.session;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * 单次 LLM 调用的 token 使用统计。
 * <p>对应 SDK 的 {@code Usage} 对象，只保留可序列化的字段。
 *
 * @author hoppinzq
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
public class TokenUsage {
    /**
     * 输入 token 数（必选）
     */
    private Long inputTokens;

    /**
     * 输出 token 数（必选）
     */
    private Long outputTokens;

    /**
     * 缓存命中 token 数（prompt caching 读命中）
     */
    private Long cacheReadTokens;

    /**
     * 缓存创建 token 数（新写入缓存）
     */
    private Long cacheCreationTokens;

    /**
     * 产生此 usage 的时间戳（便于分析不同时段的消耗）
     */
    private String timestamp;

    /**
     * 计算本次调用的总 token 数
     */
    public long getTotalTokens() {
        long total = inputTokens != null ? inputTokens : 0;
        total += outputTokens != null ? outputTokens : 0;
        return total;
    }

    /**
     * 计算缓存命中率：缓存命中 / (缓存命中 + 实际输入)。
     * <p>注：Anthropic API 的 {@code input_tokens} 与 {@code cache_read_input_tokens}
     * 是独立统计，后者是额外从 prompt cache 读取的 token 数。
     */
    public double getCacheHitRate() {
        long cached = cacheReadTokens != null ? cacheReadTokens : 0;
        long input = inputTokens != null ? inputTokens : 0;
        long totalInput = cached + input;
        if (totalInput == 0) {
            return 0.0;
        }
        return (double) cached / totalInput;
    }
}

package com.hoppinzq.agent.base;

import com.anthropic.client.AnthropicClient;
import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.hoppinzq.agent.command.AgentCommandHandler;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.session.SubAgentSessionResult;
import com.hoppinzq.agent.tool.ToolDefinition;
import com.hoppinzq.agent.tool.skill.SkillLoader;
import lombok.Data;

import java.util.*;

import static com.hoppinzq.agent.constant.AIConstants.*;

/**
 * 智能体基类
 * @author hoppinzq
 */
@Data
public class ZQAgent {
    private String systemPrompt;
    private final Scanner scanner;
    private final String model;
    protected final AnthropicClient client;
    private final List<ToolDefinition> tools;
    protected List<MessageParam> messageParams = new ArrayList<>();
    private String taskResult;
    private boolean taskCompleted = false;
    /**
     * 可选的命令处理器；设置后可处理 /stats、/usage、/skills、/exit 等特殊命令。
     */
    private AgentCommandHandler commandHandler;

    /**
     * 会话管理器
     */
    protected SessionManager sessionManager;

    public ZQAgent(AnthropicClient client, String model, List<ToolDefinition> tools) {
        this.client = client;
        this.model = model;
        this.scanner = new Scanner(System.in);
        this.tools = tools;
    }

    /**
     * 设置会话管理器，同时初始化命令处理器。
     * 子类可以重写此方法以提供额外的命令处理器（如 compact 命令）。
     */
    public void setSessionManager(SessionManager sessionManager, SkillLoader skillLoader) {
        this.sessionManager = sessionManager;
        this.commandHandler = sessionManager != null ? createCommandHandler(sessionManager, skillLoader) : null;
    }

    /**
     * 创建命令处理器。子类可以重写此方法以提供自定义的命令处理器。
     *
     * @param sessionManager 会话管理器
     * @param skillLoader 技能加载器
     * @return 命令处理器，默认不包含 compact 命令支持
     */
    protected AgentCommandHandler createCommandHandler(SessionManager sessionManager, SkillLoader skillLoader) {
        return new AgentCommandHandler(sessionManager, skillLoader, null);
    }

    public void run() {
        if (sessionManager != null) {
            int n = sessionManager.historySize();
            if (n > 0) {
                sessionManager.populate(messageParams);
                System.out.printf("\u001b[90m已恢复会话 %s，共 %d 条历史消息\u001b[0m%n",
                        sessionManager.getSessionId(), n);
            } else {
                System.out.printf("\u001b[90m新会话 %s\u001b[0m%n", sessionManager.getSessionId());
            }
        }
        System.out.println("开始对话吧（输入 /stats 查看统计，/usage 查看明细，/skills 查看技能，/tokens 查看上下文，/transcripts 查看压缩历史，/compact 手动压缩，/exit 退出）");
        while (true) {
            System.out.print("\u001b[94m你\u001b[0m: ");
            String userInput = scanner.nextLine();
            if (userInput.isEmpty()) {
                continue;
            }
            // 特殊命令：不发送给 LLM
            if (commandHandler != null && commandHandler.isCommand(userInput)) {
                commandHandler.handleCommand(userInput);
                continue;
            }
            MessageParam userMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(userInput)
                    .build();
            appendMessage(userMessage);

            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                System.out.println("错误: " + e.getMessage());
                e.printStackTrace();
                continue;
            }
            appendMessage(message.toParam());
            recordUsageIfNeeded(message);
            // 每次 create 后都打印 assistant 的文本输出，避免纯文本回复（无工具调用）被静默吞掉
            printText(message);

            // 官方推荐的 canonical agentic loop：以 stop_reason == TOOL_USE 为循环条件
            while (isToolUse(message)) {
                MessageParam toolResultMessage = executeToolCalls(message);
                appendMessage(toolResultMessage);

                try {
                    message = chatMessage(messageParams);
                } catch (Exception e) {
                    System.out.println("错误: " + e.getMessage());
                    break;
                }
                appendMessage(message.toParam());
                recordUsageIfNeeded(message);
                printText(message);
            }
            // 非 TOOL_USE 退出：检查是否被截断
            warnIfTruncated(message);
        }
    }

    /**
     * 打印 assistant 消息中的所有文本块。空文本跳过。
     */
    private void printText(Message message) {
        for (ContentBlock content : message.content()) {
            if (content.isText()) {
                String text = content.text().map(TextBlock::text).orElse("");
                if (!text.isBlank()) {
                    System.out.printf("\u001b[93mAI\u001b[0m: %s%n", text);
                }
            }
        }
    }

    /**
     * 判断是否需要继续工具循环。
     * <p>官方推荐以 {@code stop_reason == TOOL_USE} 而非遍历 content，
     * 因为模型可能输出空 tool_use 或被 max_tokens 截断，stop_reason 更可靠。
     */
    private boolean isToolUse(Message message) {
        return message.stopReason()
                .map(StopReason.TOOL_USE::equals)
                .orElse(false);
    }

    /** 命中 MAX_TOKENS 时打印警告，避免静默截断工具调用导致死循环。 */
    private void warnIfTruncated(Message message) {
        boolean maxTokens = message.stopReason()
                .map(StopReason.MAX_TOKENS::equals)
                .orElse(false);
        if (maxTokens) {
            System.out.printf("\u001b[91m[警告]\u001b[0m 本轮回复被 max_tokens=%d 截断，工具调用可能不完整。建议调大 MAX_TOKENS。%n",
                    MAX_TOKENS);
        }
    }

    /**
     * 执行一轮 assistant 回复中的所有工具调用，返回封装好的 user 角色 tool_result 消息。
     * <p>文本块已由 {@link #printText(Message)} 处理，这里只负责工具；
     * 找不到工具或执行抛异常都会被标记为 isError=true 回灌给模型。
     */
    private MessageParam executeToolCalls(Message message) {
        List<ContentBlockParam> toolResults = new ArrayList<>();
        for (ContentBlock content : message.content()) {
            if (!content.isToolUse()) {
                continue;
            }
            ToolUseBlock toolUse = content.asToolUse();
            System.out.printf("\u001b[96m工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

            String toolResult = null;
            Exception toolError = null;
            ToolDefinition matched = null;
            for (ToolDefinition tool : tools) {
                if (tool.getName().equals(toolUse.name())) {
                    matched = tool;
                    break;
                }
            }
            if (matched == null) {
                toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                System.out.printf("\u001b[91m错误\u001b[0m: %s%n", toolError.getMessage());
            } else {
                try {
                    toolResult = invokeTool(matched, toolUse._input());
                    System.out.printf("\u001b[92m结果\u001b[0m: %s%n", toolResult);
                } catch (Exception e) {
                    toolError = e;
                    System.out.printf("\u001b[91m错误\u001b[0m: %s%n", e.getMessage());
                    e.printStackTrace();
                }
            }

            toolResults.add(ContentBlockParam.ofToolResult(
                    ToolResultBlockParam.builder()
                            .toolUseId(toolUse.id())
                            .content(toolError != null ? toolError.getMessage() : toolResult)
                            .isError(toolError != null)
                            .build()
            ));
        }
        return MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(MessageParam.Content.ofBlockParams(toolResults))
                .build();
    }

    /**
     * 记录本次 LLM 调用的 token 使用情况（若设置了 SessionManager）。
     */
    private void recordUsageIfNeeded(Message message) {
        if (sessionManager != null && message.usage() != null) {
            sessionManager.recordUsage(message.usage());
        }
    }

    /**
     * 向 messageParams 追加一条消息；若设置了 {@link SessionManager}，
     * 同步持久化。所有需要记录历史的追加都应走此方法。
     */
    protected void appendMessage(MessageParam param) {
        messageParams.add(param);
        if (sessionManager != null) {
            sessionManager.onMessageAppended(param);
        }
    }

    /**
     * 工具执行后的回调钩子，子类可重写以注入额外内容（如提醒、压缩等）。
     * 注意：基类的 {@link #executeToolCalls(Message)} 不再调用此方法；
     * 仅为兼容已有子类重写而保留。
     */
    protected void onToolExecution(List<ContentBlockParam> toolResults) {
        // 默认空实现
    }

    private String invokeTool(ToolDefinition tool, JsonValue input) {
        if (tool.getType() == null) {
            if (input.asObject().isEmpty()) {
                throw new IllegalArgumentException("工具 '" + tool.getName() + "' 参数不是 JSON 对象");
            }
            ObjectNode root = OBJECT_MAPPER.createObjectNode();
            root.set("input", input.convert(JsonNode.class));
            root.put("tool_name", tool.getName());
            return tool.getFunction().apply(root.toString());
        } else {
            return tool.getFunction().apply(Objects.requireNonNull(input.convert(tool.getType())).toString());
        }
    }

    protected Message chatMessage(List<MessageParam> messageParams){
        // 准备工具配置
        List<ToolUnion> anthropicTools = new ArrayList<>();
        for (ToolDefinition tool : tools) {
            anthropicTools.add(ToolUnion.ofTool(
                    Tool.builder()
                            .name(tool.getName())
                            .description(tool.getDescription())
                            .inputSchema(tool.getInputSchema())
                            .build()
            ));
        }
        MessageCreateParams.Builder messageBuilder = MessageCreateParams.builder()
                .model(model)
                .messages(messageParams)
                .tools(anthropicTools);

        if(systemPrompt != null && !systemPrompt.isEmpty()){
            messageBuilder.system(systemPrompt);
        }

         messageBuilder.maxTokens(MAX_TOKENS);

        MessageCreateParams params = messageBuilder.build();
        return client.messages().create(params);
    }

    public String runTask(String prompt) {
        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return "Error: " + e.getMessage();
            }
            messageParams.add(message.toParam());

            List<ContentBlockParam> toolResults = new ArrayList<>();
            boolean hasToolUse = false;

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                } else if (content.isToolUse()) {
                    hasToolUse = true;
                    ToolUseBlock toolUse = content.asToolUse();
                    System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                    if ("task_completed".equals(toolUse.name())) {
                        try {
                            JsonValue input = toolUse._input();
                            Optional<Map<String, JsonValue>> object = input.asObject();
                            if (object.isPresent()) {
                                JsonValue res = object.get().get("result");
                                if (res != null && res.asString().isPresent()) {
                                    return res.asString().get().toString();
                                }
                            }
                            return "Task completed.";
                        } catch (Exception e) {
                            return "Error parsing task_completed: " + e.getMessage();
                        }
                    }

                    String toolResult = null;
                    Exception toolError = null;
                    boolean toolFound = false;

                    for (ToolDefinition tool : tools) {
                        if (tool.getName().equals(toolUse.name())) {
                            try {
                                JsonValue input = toolUse._input();
                                toolResult = invokeTool(tool, input);
                                System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                            } catch (Exception e) {
                                toolError = e;
                                System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                                e.printStackTrace();
                            }
                            toolFound = true;
                            break;
                        }
                    }

                    if (!toolFound) {
                        toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                    }

                    if (toolError != null) {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolError.getMessage())
                                        .isError(true)
                                        .build()
                        ));
                    } else {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolResult)
                                        .isError(false)
                                        .build()
                        ));
                    }
                }
            }

            if (!hasToolUse) {
                // Return the text response as result if no tools used
                warnIfTruncated(message);
                return message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
            }
            MessageParam.Content content = MessageParam.Content.ofBlockParams(toolResults);
            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(content)
                    .build();
            messageParams.add(toolResultMessage);
        }
    }

    /**
     * 执行任务并返回包含 token 使用情况的结果
     *
     * @param prompt 任务提示词
     * @return 包含结果和 token 使用情况的 SubAgentSessionResult
     */
    public SubAgentSessionResult runTaskWithTokenUsage(String prompt) {
        long totalInputTokens = 0;
        long totalOutputTokens = 0;

        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return SubAgentSessionResult.error("Error: " + e.getMessage());
            }
            messageParams.add(message.toParam());

            // 累积 token 使用情况
            if (message.usage() != null) {
                totalInputTokens += message.usage().inputTokens();
                totalOutputTokens += message.usage().outputTokens();
            }

            List<ContentBlockParam> toolResults = new ArrayList<>();
            boolean hasToolUse = false;

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    if (!result.isBlank()) {
                        System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                    }
                } else if (content.isToolUse()) {
                    hasToolUse = true;
                    ToolUseBlock toolUse = content.asToolUse();
                    System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                    if ("task_completed".equals(toolUse.name())) {
                        try {
                            JsonValue input = toolUse._input();
                            Optional<Map<String, JsonValue>> object = input.asObject();
                            if (object.isPresent()) {
                                JsonValue res = object.get().get("result");
                                if (res != null && res.asString().isPresent()) {
                                    return SubAgentSessionResult.success(
                                            res.asString().get().toString(),
                                            totalInputTokens,
                                            totalOutputTokens);
                                }
                            }
                            return SubAgentSessionResult.success("Task completed.", totalInputTokens, totalOutputTokens);
                        } catch (Exception e) {
                            return SubAgentSessionResult.error("Error parsing task_completed: " + e.getMessage());
                        }
                    }

                    String toolResult = null;
                    Exception toolError = null;
                    boolean toolFound = false;

                    for (ToolDefinition tool : tools) {
                        if (tool.getName().equals(toolUse.name())) {
                            try {
                                JsonValue input = toolUse._input();
                                toolResult = invokeTool(tool, input);
                                System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                            } catch (Exception e) {
                                toolError = e;
                                System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                                e.printStackTrace();
                            }
                            toolFound = true;
                            break;
                        }
                    }

                    if (!toolFound) {
                        toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                    }

                    if (toolError != null) {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolError.getMessage())
                                        .isError(true)
                                        .build()
                        ));
                    } else {
                        toolResults.add(ContentBlockParam.ofToolResult(
                                ToolResultBlockParam.builder()
                                        .toolUseId(toolUse.id())
                                        .content(toolResult)
                                        .isError(false)
                                        .build()
                        ));
                    }
                }
            }

            if (!hasToolUse) {
                warnIfTruncated(message);
                String result = message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
                return SubAgentSessionResult.success(result, totalInputTokens, totalOutputTokens);
            }

            MessageParam.Content content = MessageParam.Content.ofBlockParams(toolResults);
            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(content)
                    .build();
            messageParams.add(toolResultMessage);
        }
    }
}

package com.hoppinzq.agent.session;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

import static com.hoppinzq.agent.constant.AIConstants.OBJECT_MAPPER;
import static com.hoppinzq.agent.constant.AIConstants.ROOT;

/**
 * 会话文件持久化。负责 {@code .sessions/<sessionId>.json} 的读写。
 * <p>仅关心文件 IO 与 JSON 序列化，不耦合 agent / SDK 类型，便于复用与测试。
 * <ul>
 *   <li>写入采用「临时文件 +原子 rename」避免崩溃导致半截文件</li>
 *   <li>sessionId 仅允许字母数字与少量安全字符，杜绝路径穿越</li>
 * </ul>
 *
 * @author hoppinzq
 */
public class SessionStore {

    private static final String SESSION_DIR = ".sessions";
    private static final String SUFFIX = ".json";

    private final Path dir;
    private final ObjectMapper mapper;

    public SessionStore() {
        this(Paths.get(ROOT, SESSION_DIR), OBJECT_MAPPER);
    }

    public SessionStore(Path dir, ObjectMapper mapper) {
        this.dir = dir;
        this.mapper = mapper;
    }

    /**
     * 确保会话目录存在。
     */
    private void ensureDir() {
        try {
            Files.createDirectories(dir);
        } catch (IOException e) {
            throw new RuntimeException("无法创建会话目录: " + dir.toAbsolutePath(), e);
        }
    }

    /**
     * 校验 sessionId 安全性，并返回对应的会话文件路径。
     */
    public Path pathOf(String sessionId) {
        if (sessionId == null || !sessionId.matches("[A-Za-z0-9_\\-:.]+")) {
            throw new IllegalArgumentException("非法 sessionId: " + sessionId);
        }
        return dir.resolve(sessionId + SUFFIX);
    }

    /**
     * 保存（覆盖）指定会话的数据（消息 + token 统计）。
     */
    public void save(String sessionId, SessionData data) {
        ensureDir();
        Path target = pathOf(sessionId);
        Path tmp = target.resolveSibling(target.getFileName() + ".tmp");
        try {
            mapper.writeValue(tmp.toFile(), data);
            // Windows 上需要先删除目标文件，否则 Files.move 可能失败
            if (Files.exists(target)) {
                try {
                    Files.delete(target);
                } catch (IOException e) {
                    // 如果删除失败，尝试直接复制
                    Files.copy(tmp, target, StandardCopyOption.REPLACE_EXISTING);
                    Files.deleteIfExists(tmp);
                    return;
                }
            }
            try {
                Files.move(tmp, target, StandardCopyOption.ATOMIC_MOVE);
            } catch (AtomicMoveNotSupportedException ame) {
                // 跨文件系统时退化为普通移动
                Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
            }
        } catch (IOException e) {
            throw new RuntimeException("保存会话失败: " + sessionId, e);
        }
    }

    /**
     * 加载指定会话；不存在则返回空数据。
     * <p>兼容旧版本纯列表格式：若文件根节点是数组而非对象，自动迁移。
     */
    public SessionData load(String sessionId) {
        Path file = pathOf(sessionId);
        if (!Files.exists(file)) {
            return SessionData.builder().messages(new ArrayList<>()).build();
        }
        try {
            // 先尝试读取为 SessionData 对象
            try {
                SessionData data = mapper.readValue(file.toFile(), SessionData.class);
                if (data != null) {
                    if (data.getMessages() == null) {
                        data.setMessages(new ArrayList<>());
                    }
                    if (data.getUsage() == null) {
                        data.setUsage(new ArrayList<>());
                    }
                    return data;
                }
            } catch (IOException e) {
                // 可能是旧格式的纯列表，尝试迁移
            }

            // 兼容旧版本：尝试读取为纯列表
            List<SessionMessage> list = mapper.readValue(file.toFile(),
                    new TypeReference<List<SessionMessage>>() {});
            if (list != null) {
                // 迁移到新格式
                return SessionData.builder()
                        .messages(list)
                        .usage(new ArrayList<>())
                        .build();
            }
            return SessionData.builder().messages(new ArrayList<>()).build();
        } catch (IOException e) {
            throw new RuntimeException("加载会话失败: " + sessionId, e);
        }
    }

    /**
     * 是否存在该会话。
     */
    public boolean exists(String sessionId) {
        return Files.exists(pathOf(sessionId));
    }

    /**
     * 列出所有已存在的 sessionId（不含后缀）。
     */
    public List<String> listIds() {
        if (!Files.exists(dir)) {
            return List.of();
        }
        List<String> ids = new ArrayList<>();
        try (Stream<Path> s = Files.list(dir)) {
            s.filter(Files::isRegularFile)
                    .forEach(p -> {
                        String name = p.getFileName().toString();
                        if (name.endsWith(SUFFIX)) {
                            ids.add(name.substring(0, name.length() - SUFFIX.length()));
                        }
                    });
        } catch (IOException e) {
            throw new RuntimeException("列出会话失败", e);
        }
        ids.sort(java.util.Comparator.reverseOrder());
        return ids;
    }
}

